--------------------------------------------------------------------------------
-- BLOCKS
--------------------------------------------------------------------------------

local function setPickupMetadata(block, colorName, renderRole)
    block:SetAttribute("RenderRole", renderRole or "PickupObject")
    block:SetAttribute("ItemColorName", colorName)
    block:SetAttribute("IsPickupObject", true)
    block:SetAttribute("IsCarryable", true)
    block:SetAttribute("CarryKind", renderRole or "Carryable")
end

local function createBlock(name, position, colorName)
    local existing = findWorkspaceChild(name)
    if existing then
        setPickupMetadata(existing, colorName, "PickupObject")
        trackedBlocks[existing] = true
        return existing
    end
    local block = Instance.new("Part")
    block.Name = name
    block.Size = Vector3.new(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE)
    block.Position = position
    block.Anchored = false
    block.Material = Enum.Material.Slate
    block.Color = blockColors[colorName]
    block.CustomPhysicalProperties = stonePhysics -- upstream: the light blockPhysics; at block scale the body shoved them
    setPickupMetadata(block, colorName, "PickupObject")
    block.Parent = Workspace
    trackedBlocks[block] = true
    return block
end

-- A carryable piece other than the play blocks: quarried stones, logs, boulders, tools and the ladder.
local function createPiece(name, cframe, size, color, renderRole, physics, modelUrl, shape)
    local piece = Instance.new("Part")
    piece.Name = name
    piece.Size = size
    if shape then
        piece.Shape = shape
    end
    piece.CFrame = cframe
    piece.Anchored = false
    piece.Material = renderRole == "Log" and Enum.Material.Wood or Enum.Material.Slate
    piece.Color = color
    piece.CustomPhysicalProperties = physics
    setPickupMetadata(piece, "Slate", renderRole)
    if modelUrl then
        piece:SetAttribute("ModelUrl", modelUrl)
    end
    piece.Parent = Workspace
    trackedBlocks[piece] = true
    return piece
end

-- Things that belong to the island and turn up again at home if lost (in the sea).
local KEEPSAKES = {
    Hammer_1 = function()
        local p = createPiece("Hammer_1", CFrame.new(HAMMER_HOME), HAMMER_SIZE, Color3.fromRGB(140, 96, 60), "Tool",
            blockPhysics, ART.Hammer)
        p:SetAttribute("ToolKind", "Hammer")
    end,
    Axe_1 = function()
        local p = createPiece("Axe_1", CFrame.new(AXE_HOME), AXE_SIZE, Color3.fromRGB(150, 110, 70), "Tool",
            blockPhysics, ART.Axe)
        p:SetAttribute("ToolKind", "Axe")
    end,
    Ladder_1 = function() -- lying flat until someone sets it up
        createPiece("Ladder_1", CFrame.new(LADDER_HOME) * CFrame.fromOrientation(math.rad(90), 0, 0), LADDER_SIZE,
            Color3.fromRGB(176, 132, 84), "Ladder", woodPhysics, ART.Ladder)
    end,
}
for _, b in ipairs(BOULDERS) do
    KEEPSAKES[b.name] = function()
        local p = createPiece(b.name, CFrame.new(b.pos[1], b.pos[2], b.pos[3]),
            Vector3.new(BOULDER_DIAMETER, BOULDER_DIAMETER, BOULDER_DIAMETER), Color3.fromRGB(112, 108, 102), "Boulder",
            stonePhysics, ART.Boulder, Enum.PartType.Ball)
        p:SetAttribute("Heavy", true)
        p.Anchored = true -- held where it lies from the start: a ball pushed by the rock beside it never stopped rolling
        p:SetAttribute("Settled", true)
    end
end
local function restoreKeepsakes()
    for name, make in pairs(KEEPSAKES) do
        if not findWorkspaceChild(name) then
            make()
        end
    end
end
restoreKeepsakes()

local function createRock(name, position, size)
    local existing = findWorkspaceChild(name)
    if existing then
        setPickupMetadata(existing, "Slate", "Rock")
        existing.Color = ROCK_COLOR
        trackedBlocks[existing] = true
        return existing
    end

    local rock = Instance.new("Part")
    rock.Name = name
    rock.Size = size
    rock.Position = position
    rock.Anchored = false
    rock.Material = Enum.Material.Slate
    rock.Color = ROCK_COLOR
    rock.CustomPhysicalProperties = PhysicalProperties.new(
        8.0,
        0.9,
        0.0,
        1.0,
        1.0
    )
    setPickupMetadata(rock, "Slate", "Rock")
    rock.Parent = Workspace
    trackedBlocks[rock] = true
    return rock
end

local function createRing(name, position, colorName, rotationDegrees, size)
    local pitch = 0
    local yaw = 0
    local roll = 0
    if rotationDegrees then
        pitch = rotationDegrees[1] or pitch
        yaw = rotationDegrees[2] or yaw
        roll = rotationDegrees[3] or roll
    end
    local spawnCFrame = CFrame.new(position) * CFrame.Angles(math.rad(pitch), math.rad(yaw), math.rad(roll))

    local existing = findWorkspaceChild(name)
    if existing then
        setPickupMetadata(existing, colorName, "Ring")
        -- Snap ring to canonical spawn on script load so layout edits take effect without a db wipe.
        existing.Anchored = false
        existing.CFrame = spawnCFrame
        existing.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        existing.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        trackedBlocks[existing] = true
        return existing
    end
    local ring = Instance.new("Part")
    ring.Name = name
    ring.Size = size
    ring.Shape = Enum.PartType.Ring
    ring.CFrame = spawnCFrame
    ring.Anchored = false
    ring.Material = Enum.Material.Plastic
    ring.Color = blockColors[colorName]
    ring.CustomPhysicalProperties = PhysicalProperties.new(
        0.45,
        0.35,
        0.18,
        1.0,
        1.0
    )
    setPickupMetadata(ring, colorName, "Ring")
    ring.Parent = Workspace
    trackedBlocks[ring] = true
    return ring
end

-- Godling (ADR-005): the 12 starting blocks lie side by side on grid cells, one layer (4 x 3), instead of
-- upstream's tumble from the sky: at block scale they would land on each other, and a pile two layers high
-- would already count as a wall Godling never built.
local baseBlockPile = {}
for i = 0, 11 do
    baseBlockPile[i + 1] = { color = "Slate", pos = Vector3.new(ISLAND.pile[1] + (i % 4) * BLOCK_SIZE, BLOCK_SIZE / 2,
        ISLAND.pile[2] + math.floor(i / 4) * BLOCK_SIZE) }
end

for index, blockDef in ipairs(baseBlockPile) do
    createBlock("Block_" .. index, blockDef.pos, blockDef.color)
end
impactBlockCounter = #baseBlockPile

local rock = createRock("Rock_1", ROCK_SPAWN_POSITION, ROCK_SIZE)

if ENABLE_LARGE_RING then
    createRing("Ring_1", Vector3.new(40, 0.28 - SAND_DROP, -42), "Yellow", { 0, 32, 0 }, Vector3.new(3.6, 0.56, 3.6))
end

--------------------------------------------------------------------------------
-- PLAYER
--------------------------------------------------------------------------------

local function getHumanoidRootPart(player)
    local character = player.Character
    if character then
        return character:FindFirstChild("HumanoidRootPart")
    end
    return nil
end

local function setPlayerBlockState(player, block)
    -- Intentionally keep pickup/held state implicit in observations.
    -- Agents can infer state from world changes and LastActionResult.
end

local function setupPlayer(player, shouldSpawnAtStart)
    local humanoid = nil
    local character = player.Character
    if character then
        humanoid = character:FindFirstChild("Humanoid")
    end

    if player.Name == SKY_PLAYER then -- the guest panel: no body on the island; it stands on its pedestal (sky.parkGuest)
        local hrp = character and character:FindFirstChild("HumanoidRootPart")
        if hrp then
            hrp.Position = SKY_PARKING
        end
        player:SetAttribute("LastActionResult", "Ready")
        return
    end

    if humanoid then
        humanoid.WalkSpeed = 16
        humanoid.JumpPower = JUMP_POWER -- upstream: 50
        player:SetAttribute("BaseWalkSpeed", humanoid.WalkSpeed) -- carrying a boulder halves it
        player:SetAttribute("WalkSpeed", humanoid.WalkSpeed) -- the pace now (the rain slows it too)
    end

    if character then
        character:SetAttribute("ModelUrl", "asset://godling.glb")

        local hrp = character:FindFirstChild("HumanoidRootPart")
        if hrp then
            hrp:SetAttribute("ModelUrl", "asset://godling.glb") -- the renderer reads the model from the root part
            hrp:SetAttribute("ModelYawOffsetDeg", 180)
            if shouldSpawnAtStart ~= false then
                hrp.Position = PLAYER_SPAWN_POSITION
            end
        end
    end

    player:SetAttribute("LastActionResult", "Ready")
end

local function cleanupPlayer(player)
    local heldBlock = heldBlocksByPlayer[player]
    if heldBlock then
        heldBlocksByPlayer[player] = nil
        trackedBlocks[heldBlock] = nil
        rockImpactStates[heldBlock] = nil
        if heldBlock.Parent then
            heldBlock:Destroy()
        end
    end
end

local function resetPlayerToSpawn(player)
    local character = player.Character
    if not character then
        return
    end

    local hrp = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChild("Humanoid")
    if hrp then
        hrp.Position = PLAYER_SPAWN_POSITION
        hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end
    if humanoid then
        humanoid:CancelMoveTo()
    end
end

local function releaseBlockReferences(block)
    for player, heldBlock in pairs(heldBlocksByPlayer) do
        if heldBlock == block then
            heldBlocksByPlayer[player] = nil
            setPlayerBlockState(player, nil)
            player:SetAttribute("LastActionResult", "ResetAfterFall")
        end
    end

    local i = 1
    while i <= #placingBlocks do
        if placingBlocks[i].block == block then
            table.remove(placingBlocks, i)
        else
            i = i + 1
        end
    end

    local thrownIndex = 1
    while thrownIndex <= #thrownBlocks do
        if thrownBlocks[thrownIndex].block == block then
            table.remove(thrownBlocks, thrownIndex)
        else
            thrownIndex = thrownIndex + 1
        end
    end
end

local function destroyBlock(block)
    if not block.Parent then
        return
    end
    releaseBlockReferences(block)
    rockImpactStates[block] = nil
    trackedBlocks[block] = nil
    block:Destroy()
end

local function spawnImpactCubes(origin, count)
    for i = 1, count do
        impactBlockCounter = impactBlockCounter + 1
        local angle = (i / count) * math.pi * 2
        local radius = 1.1 + 0.35 * ((i - 1) % 3)
        local spawnOffset = Vector3.new(math.cos(angle) * radius, 0.9 + 0.15 * ((i - 1) % 2), math.sin(angle) * radius)
        local cube = createBlock("ImpactBlock_" .. impactBlockCounter, origin + spawnOffset, "Slate")
        cube.AssemblyLinearVelocity = Vector3.new(
            math.cos(angle) * (2.5 + i * 0.2),
            4.5 + i * 0.25,
            math.sin(angle) * (2.5 + i * 0.2)
        )
        cube.AssemblyAngularVelocity = Vector3.new(0, 6 + i, 0)
    end
end

local function armRockImpact(rockPart)
    rockImpactStates[rockPart] = {
        ignoreUntil = os.clock() + ROCK_IMPACT_ARM_DELAY,
        lastImpactAt = -math.huge,
    }

    rockPart.Touched:Connect(function(otherPart)
        if not otherPart or not otherPart:IsA("BasePart") or otherPart == rockPart then
            return
        end

        local state = rockImpactStates[rockPart]
        if not state then
            return
        end

        local now = os.clock()
        if now < state.ignoreUntil or now - state.lastImpactAt < ROCK_IMPACT_COOLDOWN then
            return
        end

        local speed = rockPart.AssemblyLinearVelocity.Magnitude
        if speed < ROCK_MIN_IMPACT_SPEED then
            return
        end

        local impactEnergy = 0.5 * rockPart:GetMass() * speed * speed
        if impactEnergy < ROCK_MIN_IMPACT_ENERGY then
            return
        end

        state.lastImpactAt = now
        local cubeCount = math.clamp(
            math.floor(impactEnergy / ROCK_ENERGY_PER_CUBE),
            1,
            ROCK_MAX_IMPACT_CUBES
        )
        spawnImpactCubes(rockPart.Position, cubeCount)
    end)
end

armRockImpact(rock)

--------------------------------------------------------------------------------
-- INPUT HANDLING
--------------------------------------------------------------------------------

local function getHumanoid(player)
    local character = player.Character
    if character then
        return character:FindFirstChild("Humanoid")
    end
    return nil
end

local function findNearestBlock(targetPosition, maxDistance)
    local closestBlock = nil
    local closestDistance = maxDistance

    for _, inst in ipairs(Workspace:GetDescendants()) do
        if inst:IsA("Part") and inst:GetAttribute("IsPickupObject") then
            local distance = (inst.Position - targetPosition).Magnitude
            if distance <= closestDistance then
                closestBlock = inst
                closestDistance = distance
            end
        end
    end

    return closestBlock
end

local function normalizeOrNil(vector)
    local magnitude = vector.Magnitude
    if magnitude <= 0.001 then
        return nil
    end
    return vector / magnitude
end

local function canReach(player, worldPosition, maxDistance)
    local hrp = getHumanoidRootPart(player)
    if not hrp then
        return false
    end
    return (hrp.Position - worldPosition).Magnitude <= maxDistance
end

local function setCarryPace(player, block) -- a heavy load halves the walk; rain slows it again (RainPace, WEATHER)
    local humanoid = getHumanoid(player)
    local base = player:GetAttribute("BaseWalkSpeed")
    if humanoid and base then
        humanoid.WalkSpeed = ((block and block:GetAttribute("Heavy")) and base / 2 or base)
            * (player:GetAttribute("RainPace") or 1)
        player:SetAttribute("WalkSpeed", humanoid.WalkSpeed)
    end
end

local function releaseHeldBlock(player)
    local block = heldBlocksByPlayer[player]
    if not block then
        return nil
    end

    heldBlocksByPlayer[player] = nil
    setPlayerBlockState(player, nil)
    setCarryPace(player, nil)
    return block
end

local function parsePosition(pos)
    if type(pos) ~= "table" then return nil end
    local x = tonumber(pos[1])
    local y = tonumber(pos[2])
    local z = tonumber(pos[3])
    if not x or not y or not z then return nil end
    if x ~= x or y ~= y or z ~= z then return nil end
    return Vector3.new(x, y, z)
end

local function noteReach(player)
    -- Counts pick-ups and places, so the renderer can play the character's reach animation (Godling).
    player:SetAttribute("Reaches", (player:GetAttribute("Reaches") or 0) + 1)
end

-- Which action the body just did, for the renderer to play its own clip (the art session's contract): the clip's
-- name and a counter, set together. Reaches and Strikes keep counting, so a renderer without the clips still plays
-- something. Clips: PickUp, PutDown, Throw, Chop, Mine, Carve, Spear, Shake, Kindle, Cook, Eat, Fasten, Draw, Talk,
-- WakeUp.
local function gesture(player, clip)
    player:SetAttribute("Gesture", clip)
    player:SetAttribute("Gestures", (player:GetAttribute("Gestures") or 0) + 1)
end

-- The thought bubble (ADR-009), as in The Sims: what Godling has in mind, pictured over its head, and how it feels,
-- shown by the tint of the cloud. A small, fast model reads the mind's thoughts and names both; the world only
-- keeps them for the renderer: Thought, Feeling and a Thoughts counter. It never touches LastActionResult, which
-- the body's own steps read.
local think = (function() -- a function of its own: its lists stay out of the main chunk's 200 locals
    local THOUGHT_THINGS = {}
    for _, thing in ipairs({ "coconut", "fish", "cooked_fish", "fire", "log", "block", "boulder", "axe", "hammer",
        "spear", "palm", "ladder", "raft", "ball", "help", "rescue", "sea", "lightning", "tower", "wall", "shelter",
        "explore", "night", "rain" }) do
        THOUGHT_THINGS[thing] = true
    end
    local FEELINGS = {}
    for _, feeling in ipairs({ "happy", "proud", "hopeful", "curious", "calm", "determined", "focused", "tired",
        "lonely", "worried", "frustrated", "scared", "hungry", "sad", "cold" }) do
        FEELINGS[feeling] = true
    end

    return function(player, inputData)
        local thing = inputData and tostring(inputData.thing or "")
        local feeling = inputData and tostring(inputData.feeling or "")
        if THOUGHT_THINGS[thing] and FEELINGS[feeling] then
            player:SetAttribute("Thought", thing)
            player:SetAttribute("Feeling", feeling)
            player:SetAttribute("Thoughts", (player:GetAttribute("Thoughts") or 0) + 1)
        end
    end
end)()

local function pickupBlock(player, inputData)
    if heldBlocksByPlayer[player] then
        player:SetAttribute("LastActionResult", "PickupFailed:AlreadyHolding")
        return
    end

    if not inputData or not inputData.position then
        player:SetAttribute("LastActionResult", "PickupFailed:MissingPosition")
        return
    end

    local targetPosition = parsePosition(inputData.position)
    if not targetPosition then
        player:SetAttribute("LastActionResult", "PickupFailed:InvalidPosition")
        return
    end
    if not canReach(player, targetPosition, PICKUP_RANGE) then
        player:SetAttribute("LastActionResult", "PickupFailed:OutOfRange")
        return
    end

    local block = findNearestBlock(targetPosition, 1.5)
    if not block then
        player:SetAttribute("LastActionResult", "PickupFailed:NoBlock")
        return
    end
    if block:GetAttribute("Fastened") then -- joined to what it touches; a hammer strike knocks it loose
        player:SetAttribute("LastActionResult", "PickupFailed:Fastened")
        return
    end
    if block:GetAttribute("Burning") then
        player:SetAttribute("LastActionResult", "PickupFailed:Burning")
        return
    end

    heldBlocksByPlayer[player] = block
    setCarryPace(player, block)
    wakeRestingOn(block)
    block:SetAttribute("Settled", false)
    block.Anchored = false
    block.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    block.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    block.CanCollide = false
    setPlayerBlockState(player, block)
    liftingBlocks[player] = { block = block, from = block.Position, elapsed = 0 }

    local impactState = rockImpactStates[block]
    if impactState then
        impactState.ignoreUntil = os.clock() + 0.25
    end

    player:SetAttribute("LastActionResult", "PickupSuccess")
    noteReach(player)
    gesture(player, "PickUp")
end

local function parseRotationDegrees(rotation)
    if rotation == nil then
        return nil
    end
    if type(rotation) == "number" then
        if rotation ~= rotation then
            return nil
        end
        return 0, tonumber(rotation), 0
    end
    if type(rotation) ~= "table" then
        return nil
    end

    local pitch = tonumber(rotation.pitch or rotation.x or rotation[1] or 0)
    local yaw = tonumber(rotation.yaw or rotation.y or rotation[2] or 0)
    local roll = tonumber(rotation.roll or rotation.z or rotation[3] or 0)
    if not pitch or not yaw or not roll then
        return nil
    end
    if pitch ~= pitch or yaw ~= yaw or roll ~= roll then
        return nil
    end
    return pitch, yaw, roll
end

local function getCurrentRotationCFrame(object)
    local pitch, yaw, roll = object.CFrame:ToOrientation()
    return CFrame.fromOrientation(pitch, yaw, roll)
end

local function getTargetPlacementCFrame(object, targetPosition, rotation)
    local rotationCFrame = getCurrentRotationCFrame(object)
    if rotation ~= nil then
        local pitch, yaw, roll = parseRotationDegrees(rotation)
        if pitch == nil then
            return nil
        end
        rotationCFrame = CFrame.fromOrientation(math.rad(pitch), math.rad(yaw), math.rad(roll))
    end
    return CFrame.new(targetPosition) * rotationCFrame
end

local function positionOccupied(player, targetCFrame, object)
    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { heldBlocksByPlayer[player] }

    local probe = Instance.new("Part")
    probe.Size = object.Size - Vector3.new(0.1, 0.1, 0.1) -- on the grid, neighbours touch exactly: touching is not taken
    probe.CFrame = targetCFrame
    probe.Shape = object.Shape

    local hits = Workspace:GetPartsInPart(probe, params)
    probe:Destroy()

    for _, hit in ipairs(hits) do
        if hit:IsA("Part") and hit:GetAttribute("RenderRole") ~= "SkyShadow" then -- a shadow takes no room
            return true
        end
    end

    return false
end

local function placeBlock(player, inputData)
    local block = heldBlocksByPlayer[player]
    if not block then
        player:SetAttribute("LastActionResult", "PlaceFailed:EmptyHands")
        return
    end

    if not inputData or not inputData.position then
        player:SetAttribute("LastActionResult", "PlaceFailed:MissingPosition")
        return
    end

    local targetPosition = parsePosition(inputData.position)
    if not targetPosition then
        player:SetAttribute("LastActionResult", "PlaceFailed:InvalidPosition")
        return
    end
    if not canReach(player, targetPosition, PLACE_RANGE) then
        player:SetAttribute("LastActionResult", "PlaceFailed:OutOfRange")
        return
    end

    local rotation = inputData.rotation
    if block:GetAttribute("RenderRole") == "Ladder" then -- a ladder always stands upright; only its facing turns
        local _, yaw = parseRotationDegrees(rotation or {})
        rotation = { pitch = 0, yaw = yaw or 0, roll = 0 }
    end
    if SNAPPED_ROLES[block:GetAttribute("RenderRole")] then -- blocks and logs settle into the grid (ADR-005)
        targetPosition = Vector3.new(math.floor(targetPosition.X / GRID + 0.5) * GRID, targetPosition.Y,
            math.floor(targetPosition.Z / GRID + 0.5) * GRID)
    end
    local targetCFrame = getTargetPlacementCFrame(block, targetPosition, rotation)
    if not targetCFrame then
        player:SetAttribute("LastActionResult", "PlaceFailed:InvalidRotation")
        return
    end

    if positionOccupied(player, targetCFrame, block) then
        player:SetAttribute("LastActionResult", "PlaceFailed:Occupied")
        return
    end

    local startCFrame = block.CFrame
    block.Anchored = true
    block.CanCollide = false
    releaseHeldBlock(player)

    table.insert(placingBlocks, {
        block = block,
        startCFrame = startCFrame,
        targetCFrame = targetCFrame,
        elapsed = 0,
        duration = PLACE_SECONDS,
    })

    player:SetAttribute("LastActionResult", "PlaceSuccess")
    noteReach(player)
    gesture(player, "PutDown")
end

local function clamp(value, minValue, maxValue)
    return math.max(minValue, math.min(maxValue, value))
end

local function getThrowDirection(inputData)
    if not inputData or not inputData.direction then
        return nil
    end

    local direction = parsePosition(inputData.direction)
    if not direction then
        return nil
    end
    return normalizeOrNil(direction)
end

local function getThrowSpeed(inputData)
    if not inputData or inputData.speed == nil then
        return clamp(THROW_SPEED, MIN_THROW_SPEED, MAX_THROW_SPEED)
    end

    return clamp(tonumber(inputData.speed) or THROW_SPEED, MIN_THROW_SPEED, MAX_THROW_SPEED)
end

local function throwBlock(player, inputData)
    local hrp = getHumanoidRootPart(player)
    local block = heldBlocksByPlayer[player]
    if not hrp or not block then
        player:SetAttribute("LastActionResult", "ThrowFailed:EmptyHands")
        return
    end

    if not inputData or not inputData.direction then
        player:SetAttribute("LastActionResult", "ThrowFailed:MissingDirection")
        return
    end

    local throwDirection = getThrowDirection(inputData)
    if not throwDirection then
        player:SetAttribute("LastActionResult", "ThrowFailed:InvalidDirection")
        return
    end

    local throwSpeed = getThrowSpeed(inputData)

    local blockToThrow = releaseHeldBlock(player)
    if not blockToThrow then
        player:SetAttribute("LastActionResult", "ThrowFailed:EmptyHands")
        return
    end

    blockToThrow.Anchored = false
    blockToThrow.CanCollide = false
    blockToThrow.Position = hrp.Position
        + Vector3.new(0, THROW_SPAWN_OFFSET_Y, 0)
        + throwDirection * THROW_FORWARD_OFFSET
    blockToThrow.AssemblyLinearVelocity = throwDirection * throwSpeed
        + Vector3.new(0, THROW_UPWARD_SPEED, 0)
        + hrp.AssemblyLinearVelocity * THROW_CARRY_VELOCITY_FACTOR
    blockToThrow.AssemblyAngularVelocity = Vector3.new(0, 8, 0)
    blockToThrow:SetNetworkOwner(nil)

    local impactState = rockImpactStates[blockToThrow]
    if impactState then
        impactState.ignoreUntil = os.clock() + THROW_COLLISION_GRACE_PERIOD
    end

    table.insert(thrownBlocks, {
        block = blockToThrow,
        elapsed = 0,
        duration = THROW_COLLISION_GRACE_PERIOD,
    })

    gesture(player, "Throw")
    player:SetAttribute("LastActionResult", "ThrowSuccess")
end

--------------------------------------------------------------------------------
-- BUILDING: STRIKING, FASTENING, CLIMBING (Godling, ADR-004)
--------------------------------------------------------------------------------

local function isCarried(part)
    for _, held in pairs(heldBlocksByPlayer) do
        if held == part then
            return true
        end
    end
    return false
end

local function halfExtents(part) -- the part's axis-aligned half size in the world, whatever its rotation
    local s, cf = part.Size * 0.5, part.CFrame
    local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
    return Vector3.new(math.abs(r.X) * s.X + math.abs(u.X) * s.Y + math.abs(l.X) * s.Z,
        math.abs(r.Y) * s.X + math.abs(u.Y) * s.Y + math.abs(l.Y) * s.Z,
        math.abs(r.Z) * s.X + math.abs(u.Z) * s.Y + math.abs(l.Z) * s.Z)
end

local function nearestPoint(part, point)
    local c, e = part.Position, halfExtents(part)
    return Vector3.new(clamp(point.X, c.X - e.X, c.X + e.X), clamp(point.Y, c.Y - e.Y, c.Y + e.Y),
        clamp(point.Z, c.Z - e.Z, c.Z + e.Z))
end

local function isSolid(inst)
    if not inst:IsA("BasePart") or not inst.CanCollide then
        return false
    end
    local role = inst:GetAttribute("RenderRole")
    return role ~= "Ocean" and string.sub(inst.Name, 1, 8) ~= "Boundary"
end

-- The highest solid top over (x, z) between minTop and maxTop, ignoring `except`; nil if there is none.
local function surfaceTopAt(x, z, minTop, maxTop, except)
    local best = nil
    for _, inst in ipairs(Workspace:GetChildren()) do
        if inst ~= except and isSolid(inst) then
            local c, e = inst.Position, halfExtents(inst)
            if math.abs(x - c.X) <= e.X and math.abs(z - c.Z) <= e.Z then
                local top = c.Y + e.Y
                if top >= minTop and top <= maxTop and (best == nil or top > best) then
                    best = top
                end
            end
        end
    end
    return best
end

local quarryWork = { count = 0, made = 0 }
local lastStrikeAt = {}

-- Over a long run stones and logs pile up where they are made. A new piece must not appear inside one already
-- there (the physics would fling both): try spots along the given side, then higher up, so it drops onto the pile.
local function freeSpawn(cframe, size, side)
    local s = size * 0.5
    local r, u, l = cframe.RightVector, cframe.UpVector, cframe.LookVector
    local e = Vector3.new(math.abs(r.X) * s.X + math.abs(u.X) * s.Y + math.abs(l.X) * s.Z,
        math.abs(r.Y) * s.X + math.abs(u.Y) * s.Y + math.abs(l.Y) * s.Z,
        math.abs(r.Z) * s.X + math.abs(u.Z) * s.Y + math.abs(l.Z) * s.Z)
    -- One piece's width aside (its width along `side`, not its length), its height up.
    local across, up = 2 * (math.abs(side.X) * e.X + math.abs(side.Z) * e.Z) + 0.1, 2 * e.Y + 0.05
    for lift = 0, 5 do
        for _, offset in ipairs({ 0, 1, -1, 2, -2 }) do
            local candidate = cframe + side * (offset * across) + Vector3.new(0, lift * up, 0)
            local c, clear = candidate.Position, true
            for _, inst in ipairs(Workspace:GetChildren()) do
                if isSolid(inst) then
                    local oc, oe = inst.Position, halfExtents(inst)
                    if math.abs(c.X - oc.X) < e.X + oe.X - 0.05 and math.abs(c.Y - oc.Y) < e.Y + oe.Y - 0.05
                        and math.abs(c.Z - oc.Z) < e.Z + oe.Z - 0.05 then -- touching neighbours on the grid are fine
                        clear = false
                        break
                    end
                end
            end
            if clear then
                return candidate
            end
        end
    end
    return cframe + Vector3.new(0, 5, 0)
end

-- Quarried stones come out onto the stone yard: the ring of ground cells around the quarry's foot, nearest the face
-- that was struck. Stones dropped at loose spots tumbled into a field that boxed Godling in (night run n2). The yard
-- cannot: Godling works from outside it and still reaches the face. When every yard cell holds a stone, the quarry
-- gives no more until some are carried away.
local function cellTaken(centre, size) -- anything solid inside the box (touching is fine)
    local probe = Instance.new("Part")
    probe.Size = size - Vector3.new(0.2, 0.2, 0.2)
    probe.CFrame = CFrame.new(centre)
    local hits = Workspace:GetPartsInPart(probe, OverlapParams.new())
    probe:Destroy()
    for _, hit in ipairs(hits) do
        if isSolid(hit) then
            return true
        end
    end
    return false
end

local function yardCell(quarry, nearest, body)
    local qc, qe = quarry.Position, halfExtents(quarry)
    local half, size = BLOCK_SIZE / 2, Vector3.new(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE)
    local best, bestDistance = nil, math.huge
    for gx = math.floor((qc.X - qe.X - 2 * GRID) / GRID), math.ceil((qc.X + qe.X + 2 * GRID) / GRID) do
        for gz = math.floor((qc.Z - qe.Z - 2 * GRID) / GRID), math.ceil((qc.Z + qe.Z + 2 * GRID) / GRID) do
            local x, z = gx * GRID, gz * GRID
            local gapX = math.abs(x - qc.X) - qe.X - half -- how far the cell stands off the quarry's foot
            local gapZ = math.abs(z - qc.Z) - qe.Z - half
            local inRing = math.max(gapX, gapZ) >= 0 and gapX < GRID and gapZ < GRID
            local clearOfBody = math.abs(x - body.X) >= half + 1.1 or math.abs(z - body.Z) >= half + 1.1
            local ground = surfaceTopAt(x, z, -1, 0.5)
            if inRing and clearOfBody and ground and math.abs(ground) < 0.3 then
                local centre = Vector3.new(x, ground + half + 0.02, z)
                local d = (Vector3.new(x, nearest.Y, z) - nearest).Magnitude
                if d < bestDistance and not cellTaken(centre, size) then
                    best, bestDistance = centre, d
                end
            end
        end
    end
    return best
end

local function breakStone(quarry, body, nearest)
    local cell = yardCell(quarry, nearest, body)
    if not cell then
        return "StrikeYardFull" -- the blow is not counted: there is nowhere for a stone to fall
    end
    quarryWork.count = quarryWork.count + 1
    if quarryWork.count < STRIKES_PER_STONE then
        return "StrikeHit:" .. quarryWork.count .. "/" .. STRIKES_PER_STONE
    end
    quarryWork.count = 0
    quarryWork.made = quarryWork.made + 1
    local name = "Stone_" .. quarryWork.made
    local size = Vector3.new(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE)
    createPiece(name, CFrame.new(cell), size, Color3.fromRGB(150, 146, 140), "Stone", stonePhysics, ART.Stone)
    return "StrikeBroke:" .. name
end

local logCounter = 0

local fellTree -- below: chopping and lightning both fell trees

local function chopTree(tree, body)
    local chops = (tree:GetAttribute("Chops") or 0) + 1
    if chops < CHOPS_PER_TREE then
        tree:SetAttribute("Chops", chops)
        return "StrikeHit:" .. chops .. "/" .. CHOPS_PER_TREE
    end
    tree:SetAttribute("Chops", 0)
    return "StrikeFelled:" .. table.concat(fellTree(tree, body), ",")
end

-- A tree falls away from `body`, along the grid: two logs side by side in the cells beside the stump, which stays
-- behind. (Logs that fell at a slant were pushed far off by their slanted boxes and settled askew.) `mark` (optional)
-- is applied to each log. Returns the logs' names.
function fellTree(tree, body, mark)
    local base = Vector3.new(tree.Position.X, 0, tree.Position.Z)
    local away = Vector3.new(base.X - body.X, 0, base.Z - body.Z)
    if math.abs(away.X) >= math.abs(away.Z) then
        away = Vector3.new(away.X >= 0 and 1 or -1, 0, 0)
    else
        away = Vector3.new(0, 0, away.Z >= 0 and 1 or -1)
    end
    local side = Vector3.new(-away.Z, 0, away.X)
    local yaw = math.abs(away.X) > 0.5 and 0 or math.rad(90) -- the log's length (X) along the fall
    local names = {}
    for i = 1, 2 do
        logCounter = logCounter + 1
        local spot = base + away * (tree.Size.X / 2 + LOG_SIZE.X / 2) + side * ((i - 1) * BLOCK_SIZE)
            + Vector3.new(0, LOG_SIZE.Y / 2 + 0.02, 0)
        local name = "Log_" .. logCounter
        local log = createPiece(name, freeSpawn(CFrame.new(spot) * CFrame.fromOrientation(0, yaw, 0), LOG_SIZE, side),
            LOG_SIZE, Color3.fromRGB(140, 98, 62), "Log", woodPhysics, ART.Log) -- a square beam: a round one rolled away
        if mark then
            mark(log)
        end
        names[i] = name
    end
    tree.Size = Vector3.new(tree.Size.X, BLOCK_SIZE / 2, tree.Size.Z) -- a stump half a block high
    tree.Position = Vector3.new(base.X, BLOCK_SIZE / 4, base.Z)
    tree:SetAttribute("RenderRole", "Stump")
    tree:SetAttribute("ModelUrl", ART.Stump)
    tree:SetAttribute("FelledAt", os.clock())
    return names
end

local function regrowStump(t)
    local stump = t.part
    stump.Size = Vector3.new(t.size[1], t.size[2], t.size[3])
    stump.Position = Vector3.new(t.pos[1], t.pos[2], t.pos[3])
    stump:SetAttribute("RenderRole", "Tree")
    stump:SetAttribute("ModelUrl", t.model) -- a palm grows back a palm
    stump:SetAttribute("SkyEvent", "") -- grown back by itself; a sky regrowth marks it again
end

local function regrowTrees()
    for _, t in ipairs(trees) do
        local stump = t.part
        if stump and stump.Parent and stump:GetAttribute("RenderRole") == "Stump"
            and os.clock() - (stump:GetAttribute("FelledAt") or 0) >= TREE_REGROW_SECONDS then
            regrowStump(t)
        end
    end
end

local function unfasten(piece) -- loose again: it settles where it is, or falls if nothing holds it up
    if piece:GetAttribute("RenderRole") ~= "Ladder" then -- a set-up ladder stays standing
        piece.Anchored = false
    end
    piece:SetAttribute("Fastened", false)
    return "StrikeLoosened:" .. piece.Name
end

--------------------------------------------------------------------------------
-- SURVIVAL (the user's wish, after Cast Away; ADR-007): hunger, coconuts, a carved spear, fish, and a volleyball
--------------------------------------------------------------------------------

-- Hunger empties in about an hour. Then health drains over about half an hour; at none, Godling faints, drops what it
-- holds, and wakes by the raft half fed and weak. A coconut fills 15, a raw fish 20, a fish cooked over a fire 50.
local HUNGER_EMPTY_SECONDS, STARVE_SECONDS = 3600, 1800
local FOOD = { Coconut = 15, Catch = 20, CookedCatch = 50 }
local FAINT_HUNGER, FAINT_HEALTH = 50, 30
-- Hurt and healing: lightning striking close by, or a stone from the sky landing close by, takes health. Fed at
-- least half full, the body mends: from none to whole in about half an hour.
local HARM = {
    healWhenFed = 50, healSeconds = 1800,
    coldDrainSeconds = 2400, -- cold (WEATHER) takes a whole body's health in 40 minutes, and stops healing
    lightning = 35, lightningRange = 7, -- from the struck palm's trunk
    meteor = 45, meteorRange = 6, -- from where the stone lands
}
local COCONUT_SIZE, COCONUT_REGROW = 0.9, 300 -- a palm bears one ripe coconut, again 5 minutes after the last
local CARVES_PER_SPEAR, SPEAR_SIZE = 3, Vector3.new(0.3, 0.3, 4.5)
local FISH_COUNT, FISH_SPEED, FISH_Y, FISH_SIZE = 12, 1.6, OCEAN_TOP_Y + 0.15, Vector3.new(1.3, 0.35, 0.5)
local CATCH_CHANCE, FISH_RESPAWN = 0.6, 60
local survivalCounters = { coconuts = 0, spears = 0, fish = 0, catches = 0 }
local surviving = {} -- player -> { hunger, health, beat }

local function setVitals(player, s)
    player:SetAttribute("Hunger", math.floor(s.hunger * 10 + 0.5) / 10)
    player:SetAttribute("Health", math.floor(s.health * 10 + 0.5) / 10)
    local humanoid = getHumanoid(player)
    if humanoid then
        humanoid.Health = math.max(1, s.health) -- the viewers' HP; fainting, not the engine's death, handles none
    end
end

local function faint(player, s)
    local held = releaseHeldBlock(player)
    if held then -- it drops where Godling fell
        held.Anchored = false
        held.CanCollide = true
    end
    resetPlayerToSpawn(player)
    s.hunger, s.health = FAINT_HUNGER, FAINT_HEALTH
    player:SetAttribute("Faints", (player:GetAttribute("Faints") or 0) + 1)
    setVitals(player, s)
    gesture(player, "WakeUp") -- getting up off its back by the raft
end

local function hurt(player, amount, cause)
    local s = surviving[player]
    if not s then
        return
    end
    s.health = math.max(0, s.health - amount)
    player:SetAttribute("Hurt", cause)
    player:SetAttribute("Hurts", (player:GetAttribute("Hurts") or 0) + 1)
    print(string.format("HURT %s by %s: health %.0f", player.Name, cause, s.health))
    if s.health <= 0 then
        faint(player, s)
    else
        setVitals(player, s)
    end
end

-- Everyone (but the guest panel) standing within `range` of (x, z) when the sky strikes there.
local function hurtNear(x, z, range, amount, cause)
    for _, player in ipairs(Players:GetPlayers()) do
        local hrp = player.Name ~= SKY_PLAYER and getHumanoidRootPart(player)
        if hrp then
            local dx, dz = hrp.Position.X - x, hrp.Position.Z - z
            if dx * dx + dz * dz <= range * range then
                hurt(player, amount, cause)
            end
        end
    end
end

local function tickSurvival(dt)
    for _, player in ipairs(Players:GetPlayers()) do
        local s = surviving[player]
        if player.Name == SKY_PLAYER then -- the guest panel has no body to feed (it fainted three times in run n7,
            s = nil -- and each faint parked it by the raft)
        elseif not s then
            s = { hunger = player:GetAttribute("Hunger") or 100, health = player:GetAttribute("Health") or 100, beat = 0 }
            surviving[player] = s
        end
        if s then
            if s.hunger > 0 then
                s.hunger = math.max(0, s.hunger - dt * 100 / HUNGER_EMPTY_SECONDS)
            else
                s.health = s.health - dt * 100 / STARVE_SECONDS
            end
            if s.cold then
                s.health = s.health - dt * 100 / HARM.coldDrainSeconds
            elseif s.hunger >= HARM.healWhenFed and s.health < 100 then -- well fed and warm, a body mends
                s.health = math.min(100, s.health + dt * 100 / HARM.healSeconds)
            end
            s.beat = s.beat + dt
            if s.health <= 0 then
                faint(player, s)
            elseif s.beat >= 1 then -- attributes once a second, not every frame
                s.beat = 0
                setVitals(player, s)
            end
        end
    end
end

local function eat(player)
    local held = heldBlocksByPlayer[player]
    local kind = held and held:GetAttribute("RenderRole")
    local food = held and FOOD[(kind == "Catch" and held:GetAttribute("Cooked")) and "CookedCatch" or kind]
    if not held then
        player:SetAttribute("LastActionResult", "EatFailed:EmptyHands")
        return
    end
    if not food then
        player:SetAttribute("LastActionResult", "EatFailed:NotFood")
        return
    end
    releaseHeldBlock(player)
    trackedBlocks[held] = nil
    held:Destroy()
    local s = surviving[player] or { hunger = 100, health = 100, beat = 0 }
    surviving[player] = s
    s.hunger = math.min(100, s.hunger + food)
    s.health = math.min(100, s.health + food / 4) -- a meal mends a little too
    setVitals(player, s)
    player:SetAttribute("Reaches", (player:GetAttribute("Reaches") or 0) + 1)
    gesture(player, "Eat")
    player:SetAttribute("LastActionResult", string.format("EatSuccess:%d", math.floor(s.hunger + 0.5)))
end

-- Coconuts: shake a palm and its ripe coconut drops at its foot.
local function shakePalm(player, inputData)
    local hrp = getHumanoidRootPart(player)
    local palm = inputData and inputData.name and findWorkspaceChild(tostring(inputData.name))
    if not hrp or not palm or palm:GetAttribute("RenderRole") ~= "Tree" or string.sub(palm.Name, 1, 5) ~= "Palm_" then
        player:SetAttribute("LastActionResult", "ShakeFailed:NotAPalm")
        return
    end
    if (nearestPoint(palm, hrp.Position) - hrp.Position).Magnitude > STRIKE_RANGE then
        player:SetAttribute("LastActionResult", "ShakeFailed:OutOfRange")
        return
    end
    player:SetAttribute("Strikes", (player:GetAttribute("Strikes") or 0) + 1) -- arms up at the trunk
    gesture(player, "Shake")
    if os.clock() - (palm:GetAttribute("CoconutAt") or -math.huge) < COCONUT_REGROW then
        player:SetAttribute("LastActionResult", "ShakeNothing")
        return
    end
    palm:SetAttribute("CoconutAt", os.clock())
    survivalCounters.coconuts = survivalCounters.coconuts + 1
    local name = "Coconut_" .. survivalCounters.coconuts
    local toBody = Vector3.new(hrp.Position.X - palm.Position.X, 0, hrp.Position.Z - palm.Position.Z)
    toBody = toBody.Magnitude > 0.01 and toBody.Unit or Vector3.new(1, 0, 0)
    local spot = Vector3.new(palm.Position.X, 3, palm.Position.Z) + toBody * 2.2 -- it drops between palm and shaker
    local size = Vector3.new(COCONUT_SIZE, COCONUT_SIZE, COCONUT_SIZE)
    createPiece(name, freeSpawn(CFrame.new(spot), size, Vector3.new(-toBody.Z, 0, toBody.X)), size,
        Color3.fromRGB(110, 78, 46), "Coconut", woodPhysics, ART.Coconut, Enum.PartType.Ball)
    player:SetAttribute("LastActionResult", "ShakeCoconut:" .. name)
end

-- Carving: strikes with the axe turn a log into a spear.
local function carveLog(log)
    local carves = (log:GetAttribute("Carves") or 0) + 1
    if carves < CARVES_PER_SPEAR then
        log:SetAttribute("Carves", carves)
        return "StrikeCarving:" .. carves .. "/" .. CARVES_PER_SPEAR
    end
    wakeRestingOn(log)
    local at = log.Position
    trackedBlocks[log] = nil
    log:Destroy()
    survivalCounters.spears = survivalCounters.spears + 1
    local name = "Spear_" .. survivalCounters.spears
    local p = createPiece(name, CFrame.new(Vector3.new(at.X, 0.25, at.Z)), SPEAR_SIZE, Color3.fromRGB(150, 112, 70), "Tool",
        woodPhysics, ART.Spear)
    p:SetAttribute("ToolKind", "Spear")
    return "StrikeCarved:" .. name
end

-- Fish swim the shallows along the shore. With a spear in hand, a strike that reaches one may catch it; the catch
-- lands on the sand at Godling's feet. A missed fish darts off.
local SHALLOWS = ISLAND.shallows
local swimming = {} -- fish part -> { goal, speed, dartUntil }
local fishDue = {} -- os.clock() times when a caught fish is replaced

local function overLand(x, z)
    for _, g in ipairs(groundParts) do
        if math.abs(x - g.pos[1]) <= g.size[1] / 2 and math.abs(z - g.pos[3]) <= g.size[3] / 2 then
            return true
        end
    end
    return false
end

-- A shallow spot to swim to: within reach and with open water all the way. (Fish once fell back to any spot on the
-- island and swam straight across the land to it; 9 of 12 were found under the beach and the grass.)
local function shallowNear(from, within)
    if not from then
        local p = SHALLOWS[math.random(1, #SHALLOWS)]
        return Vector3.new(p[1], FISH_Y, p[2])
    end
    local choices = {}
    for _, p in ipairs(SHALLOWS) do
        local dx, dz = p[1] - from.X, p[2] - from.Z
        local d = math.sqrt(dx * dx + dz * dz)
        if d > 1 and d <= within then
            local clear = true
            for k = 1, math.ceil(d / 1.5) do
                local t = k / math.ceil(d / 1.5)
                if overLand(from.X + dx * t, from.Z + dz * t) then
                    clear = false
                    break
                end
            end
            if clear then
                table.insert(choices, p)
            end
        end
    end
    local p = choices[math.random(1, math.max(1, #choices))]
    if not p then -- boxed in: stay put
        return Vector3.new(from.X, FISH_Y, from.Z)
    end
    return Vector3.new(p[1], FISH_Y, p[2])
end

local function spawnFish()
    survivalCounters.fish = survivalCounters.fish + 1
    local fish = Instance.new("Part")
    fish.Name = "Fish_" .. survivalCounters.fish
    fish.Size = FISH_SIZE
    fish.CFrame = CFrame.new(shallowNear(nil, 0)) * CFrame.fromOrientation(math.rad(90), 0, 0) -- upright, back up
    fish.Anchored = true
    fish.CanCollide = false
    fish.Color = Color3.fromRGB(150, 170, 190)
    fish:SetAttribute("RenderRole", "Fish")
    if ART.Fish then
        fish:SetAttribute("ModelUrl", ART.Fish)
    end
    fish.Parent = Workspace
    swimming[fish] = { goal = shallowNear(fish.Position, 12), speed = FISH_SPEED * (0.7 + 0.6 * math.random()), dartUntil = 0 }
end

local function moveFish(dt)
    for fish, f in pairs(swimming) do
        if not fish.Parent then
            swimming[fish] = nil
        else
            local to = f.goal - fish.Position
            local dist = to.Magnitude
            if dist < 0.5 then
                f.goal = shallowNear(fish.Position, 12)
            else
                local speed = f.speed * (os.clock() < f.dartUntil and 3 or 1)
                local step = to.Unit * math.min(dist, speed * dt)
                fish.CFrame = CFrame.new(fish.Position + step) * CFrame.fromOrientation(0, math.atan2(-to.Z, to.X), 0)
                    * CFrame.fromOrientation(math.rad(90), 0, 0) -- along its way, upright (the model lies on its side)
            end
        end
    end
    local now, count = os.clock(), 0
    for _ in pairs(swimming) do
        count = count + 1
    end
    for i = #fishDue, 1, -1 do
        if now >= fishDue[i] and count < FISH_COUNT then
            table.remove(fishDue, i)
            spawnFish()
            count = count + 1
        end
    end
end

local function catchFish(fish, body)
    local f = swimming[fish]
    if math.random() > CATCH_CHANCE then
        if f then -- it darts away
            f.goal = shallowNear(fish.Position, 20)
            f.dartUntil = os.clock() + 2
        end
        return "StrikeMissed:" .. fish.Name
    end
    swimming[fish] = nil
    local from = fish.Position
    fish:Destroy()
    table.insert(fishDue, os.clock() + FISH_RESPAWN)
    survivalCounters.catches = survivalCounters.catches + 1
    local name = "Catch_" .. survivalCounters.catches
    local landward = Vector3.new(body.X - from.X, 0, body.Z - from.Z)
    landward = landward.Magnitude > 0.01 and landward.Unit or Vector3.new(1, 0, 0)
    local spot = Vector3.new(body.X, 0.4, body.Z) + landward * 1.8 -- on the sand at its feet, away from the water
    createPiece(name, freeSpawn(CFrame.new(spot), FISH_SIZE, Vector3.new(-landward.Z, 0, landward.X)), FISH_SIZE,
        Color3.fromRGB(150, 170, 190), "Catch", woodPhysics, ART.Fish)
    return "StrikeCaught:" .. name
end

for _ = 1, FISH_COUNT do
    spawnFish()
end

-- Day and night (the user's choice): a 40-minute day, and Godling wakes at seven in the morning. The renderer's sun
-- follows the Clock's TimeOfDay, and so does Godling's own view: nights are dark, and a fire lights them.
local DAY_SECONDS, START_HOUR = 2400, 7
local clockPart = findWorkspaceChild("Clock") or Instance.new("Part")
clockPart.Name = "Clock"
clockPart.Size = Vector3.new(0.2, 0.2, 0.2)
clockPart.Position = Vector3.new(0, -60, 0)
clockPart.Anchored = true
clockPart.CanCollide = false
clockPart.Transparency = 1
clockPart:SetAttribute("TimeOfDay", START_HOUR)
clockPart.Parent = Workspace
local clockSeconds, clockBeat = 0, 0

local function tickClock(dt)
    clockSeconds = clockSeconds + dt
    clockBeat = clockBeat + dt
    if clockBeat >= 1 then
        clockBeat = 0
        local hour = (START_HOUR + clockSeconds / DAY_SECONDS * 24) % 24
        clockPart:SetAttribute("TimeOfDay", math.floor(hour * 100 + 0.5) / 100)
    end
end

-- Fire, hard won as in the film (the user's wish; ADR-010). There is no ready-made way to light one: rubbing a stick
-- (a struck Spear) against a log that lies still heats the wood a little more with each rub in a row. It only catches
-- once the wood is hot, after RUB_HOT rubs, and only into something dry and fine lying right beside it (a coconut's
-- husk, as Chuck's tinder was), which burns away. Nothing catches in the rain or while the wood is still damp after it,
-- and rain puts every fire out (WEATHER). A fire burns ten minutes and uses the log up; over it a raw fish cooks.
local FIRE_SECONDS, COOK_RANGE = 600, 6
local fires = {} -- fire part -> { log, untilTime }
local climate = { rain = 0, dampUntil = 0 } -- kept by WEATHER: how hard it rains, and until when wood stays damp

local function lightFire(log)
    log:SetAttribute("Burning", true)
    survivalCounters.fires = (survivalCounters.fires or 0) + 1
    local fire = Instance.new("Part")
    fire.Name = "Fire_" .. survivalCounters.fires
    fire.Size = Vector3.new(2.2, 3, 2.2)
    fire.Position = Vector3.new(log.Position.X, log.Position.Y + halfExtents(log).Y + 1.5, log.Position.Z)
    fire.Anchored = true
    fire.CanCollide = false
    fire.Material = Enum.Material.Neon
    fire.Color = Color3.fromRGB(255, 140, 40)
    fire:SetAttribute("RenderRole", "Fire")
    fire:SetAttribute("Fuel", log.Name)
    fire.Parent = Workspace
    fires[fire] = { log = log, untilTime = os.clock() + FIRE_SECONDS }
    return fire
end

-- One rub of a stick against a log (a strike with the Spear); what the strike says happened. (A function of its own:
-- its locals stay out of the main chunk's 200.)
local rubLog = (function()
    local RUB_HOT, RUB_CATCH, RUB_COOLS, TINDER_RANGE = 12, 0.04, 10, 3
    local rubbedAt = {} -- log -> when it was last rubbed

    return function(log)
        if log:GetAttribute("Burning") then
            return "StrikeRubBurning"
        end
        if climate.rain > 0.3 then
            return "StrikeRubRain"
        end
        if os.clock() < climate.dampUntil then
            return "StrikeRubDamp"
        end
        local warm = os.clock() - (rubbedAt[log] or -math.huge) <= RUB_COOLS
        local heat = (warm and log:GetAttribute("Heat") or 0) + 1 -- rubs in a row on this log
        log:SetAttribute("Heat", heat)
        rubbedAt[log] = os.clock()
        if heat < RUB_HOT then
            return "StrikeRubWarm:" .. heat
        end
        local tinder = nil
        for _, inst in ipairs(Workspace:GetChildren()) do
            if inst:IsA("BasePart") and inst:GetAttribute("RenderRole") == "Coconut" and not isCarried(inst)
                and (nearestPoint(log, inst.Position) - inst.Position).Magnitude <= TINDER_RANGE then
                tinder = inst
                break
            end
        end
        if not tinder or math.random() > RUB_CATCH * (heat - RUB_HOT + 1) then
            return "StrikeRubHot:" .. heat -- hot and smoking; nothing caught
        end
        trackedBlocks[tinder] = nil
        tinder:Destroy() -- the husk burns away
        rubbedAt[log] = nil
        log:SetAttribute("Heat", 0)
        return "StrikeRubCaught:" .. lightFire(log).Name
    end
end)()

-- Rain puts fires out (WEATHER): the fire is gone, the log is left, charred but whole.
local function douseFires()
    for fire, f in pairs(fires) do
        fires[fire] = nil
        fire:Destroy()
        if f.log.Parent then
            f.log:SetAttribute("Burning", false)
            f.log:SetAttribute("Heat", 0)
        end
        print(string.format("DOUSED %s on %s", fire.Name, f.log.Name))
    end
end

local function tickFires()
    for fire, f in pairs(fires) do
        if os.clock() >= f.untilTime or not f.log.Parent then -- burnt out: the log is ash
            fires[fire] = nil
            fire:Destroy()
            if f.log.Parent then
                wakeRestingOn(f.log)
                trackedBlocks[f.log] = nil
                f.log:Destroy()
            end
        end
    end
end

local function cook(player)
    local hrp = getHumanoidRootPart(player)
    local held = heldBlocksByPlayer[player]
    if not hrp or not held or held:GetAttribute("RenderRole") ~= "Catch" then
        player:SetAttribute("LastActionResult", "CookFailed:NotFish")
        return
    end
    if held:GetAttribute("Cooked") then
        player:SetAttribute("LastActionResult", "CookFailed:Cooked")
        return
    end
    for fire in pairs(fires) do
        local d = fire.Position - hrp.Position
        if Vector3.new(d.X, 0, d.Z).Magnitude <= COOK_RANGE then
            held:SetAttribute("Cooked", true)
            held.Color = Color3.fromRGB(165, 104, 58)
            held:SetAttribute("ModelUrl", ART.FishCooked) -- browned, with grill marks
            player:SetAttribute("Reaches", (player:GetAttribute("Reaches") or 0) + 1)
            gesture(player, "Cook")
            player:SetAttribute("LastActionResult", "CookSuccess:" .. held.Name)
            return
        end
    end
    player:SetAttribute("LastActionResult", "CookFailed:NoFire")
end

-- WEATHER (the user's wish, after run n7, where nothing made a shelter worth building; ADR-010).
-- - Showers come every 20 to 50 minutes and last 4 to 10. Now and then a wet spell sets in instead: two or three days
--   of rain without a break (the first 1.5 to 2.5 hours into a run, then every 4 to 7 hours).
-- - In heavy rain thunderstorms break: lightning strikes a palm near Godling every few minutes.
-- - Some mornings fog comes in from the sea and hides what is further than a stone's throw.
-- - Out in the rain the body is slowed and gets soaked. Nights are cold, and so is being soaked in the rain; cold wears
--   health down and stops healing. A roof overhead keeps the rain off; a roof with walls on three sides, or a fire close
--   by, keeps the cold off. Rain puts every fire out, and leaves the wood too damp to light for a while after.
-- The Clock carries Rain and Fog (0-1) for the renderer; each body carries Wet (0-100), Cold, InRain, Sheltered ("",
-- "roof" or "enclosed") and its current WalkSpeed.
local stormStrike -- with the sky events below: lightning on a palm near Godling
-- Rain, cold and shelter. Like the other newer sections, a function of its own, so its locals stay out of the main
-- chunk's (Luau allows 200 locals in one function, and the world script has come close).
local tickWeather = (function()
    local RAIN_GAP_MIN, RAIN_GAP_MAX, RAIN_MIN, RAIN_MAX = 20 * 60, 50 * 60, 4 * 60, 10 * 60
    local RAIN_FIRST_MIN, RAIN_FIRST_MAX = 8 * 60, 15 * 60 -- the first shower comes early, so a run meets it
    local SPELL_FIRST_MIN, SPELL_FIRST_MAX, SPELL_GAP_MIN, SPELL_GAP_MAX = 90 * 60, 150 * 60, 240 * 60, 420 * 60
    local SPELL_DAYS_MIN, SPELL_DAYS_MAX = 2, 3
    local STORM_RAIN, STORM_MIN, STORM_MAX = 0.85, 3 * 60, 8 * 60 -- heavy rain brings lightning, this often
    local FOG_CHANCE, FOG_FROM, FOG_UNTIL_MIN, FOG_UNTIL_MAX = 0.35, 4.5, 8.5, 10 -- some mornings, these hours
    local RAIN_FADE, FOG_FADE = 20, 60 -- seconds a shower or a fog takes to build up and to die away
    local DAMP_AFTER = 300 -- wood stays too damp to light this long after the rain
    local RAIN_PACE = 0.65 -- walking pace out in the rain
    -- Wind (the user's wish): a breeze in fair weather, stronger in the rain, a gale in a storm. It veers slowly. The
    -- Clock carries it as WindX/WindZ (direction times strength, 0-1); the renderer adds the gusts, bends the rain
    -- and sways the palms. It moves nothing in the world.
    local WIND_FAIR, WIND_RAIN, WIND_STORM, WIND_EASE = 0.25, 0.55, 1.0, 30
    local WET_SECONDS, DRY_SECONDS, FIRE_DRIES = 120, 300, 4 -- soaked through; dried out; a fire dries this much faster
    local NIGHT_FROM, NIGHT_TO = 21, 5
    local WARM_RANGE = 7 -- a fire this close warms
    local weatherState = SUPPLY_SEED + 7
    local function weatherRandom()
        weatherState = (weatherState * 16807) % 2147483647
        return weatherState / 2147483647
    end
    local function between(lo, hi)
        return lo + weatherRandom() * (hi - lo)
    end
    local weather = { raining = false, spell = false, left = between(RAIN_FIRST_MIN, RAIN_FIRST_MAX), rain = 0, beat = 0,
        clock = 0, spellDue = between(SPELL_FIRST_MIN, SPELL_FIRST_MAX), storm = between(STORM_MIN, STORM_MAX),
        fog = 0, fogUntil = nil, lastHour = nil, wind = WIND_FAIR, windDir = weatherRandom() * 2 * math.pi }
    clockPart:SetAttribute("Rain", 0)
    clockPart:SetAttribute("Fog", 0)

    local function nextWeather() -- a shower ends in a dry gap; a dry gap ends in a shower, or a wet spell when one is due
        if weather.raining then
            weather.raining, weather.spell = false, false
            weather.left = between(RAIN_GAP_MIN, RAIN_GAP_MAX)
        elseif weather.clock >= weather.spellDue then
            weather.raining, weather.spell = true, true
            weather.left = between(SPELL_DAYS_MIN, SPELL_DAYS_MAX) * DAY_SECONDS
            weather.spellDue = weather.clock + weather.left + between(SPELL_GAP_MIN, SPELL_GAP_MAX)
        else
            weather.raining = true
            weather.left = between(RAIN_MIN, RAIN_MAX)
        end
        print(string.format("WEATHER %s for %.0f min", weather.spell and "a wet spell" or weather.raining and "rain"
            or "dry", weather.left / 60))
    end

    local function tickSkies(dt, hour) -- the storm's lightning and the morning fog
        if weather.rain >= STORM_RAIN then
            weather.storm = weather.storm - dt
            if weather.storm <= 0 then
                weather.storm = between(STORM_MIN, STORM_MAX)
                stormStrike()
            end
        end
        if weather.lastHour and weather.lastHour < FOG_FROM and hour >= FOG_FROM and weatherRandom() < FOG_CHANCE then
            weather.fogUntil = between(FOG_UNTIL_MIN, FOG_UNTIL_MAX)
            print(string.format("WEATHER fog until %.1f h", weather.fogUntil))
        end
        weather.lastHour = hour
        if weather.fogUntil and (hour >= weather.fogUntil or hour < FOG_FROM - 0.5) then
            weather.fogUntil = nil
        end
        weather.fog = weather.fog + math.clamp((weather.fogUntil and 1 or 0) - weather.fog, -dt / FOG_FADE, dt / FOG_FADE)
    end

    local function anchoredIn(player, centre, size) -- held, solid things in a box (not the body, not what it carries)
        local params = OverlapParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { player.Character, heldBlocksByPlayer[player] }
        local probe = Instance.new("Part")
        probe.Size = size
        probe.CFrame = CFrame.new(centre)
        local hits = Workspace:GetPartsInPart(probe, params)
        probe:Destroy()
        for _, hit in ipairs(hits) do
            if hit.Anchored and isSolid(hit) then
                return true
            end
        end
        return false
    end

    -- "roof": something held overhead, within 10 above the crown; "enclosed": that, and walls on three sides or more.
    local function shelterOf(player, hrp)
        local p = hrp.Position
        if not anchoredIn(player, p + Vector3.new(0, 2.6 + 5, 0), Vector3.new(1.2, 10, 1.2)) then
            return ""
        end
        local sides = 0
        for _, d in ipairs({ Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1) }) do
            local size = Vector3.new(d.X ~= 0 and 2.6 or 1.2, 2, d.Z ~= 0 and 2.6 or 1.2) -- from 1.1 to 3.7 out, chest high
            if anchoredIn(player, p + d * 2.4 + Vector3.new(0, 0.5, 0), size) then
                sides = sides + 1
            end
        end
        return sides >= 3 and "enclosed" or "roof"
    end

    local function tickWeather(dt)
        weather.clock = weather.clock + dt
        weather.left = weather.left - dt
        if weather.left <= 0 or (not weather.raining and weather.clock >= weather.spellDue) then
            nextWeather()
        end
        -- A wet spell swells and eases (0.6 to 1) through its days; a shower comes down hard.
        local target = weather.raining and (weather.spell and 0.8 + 0.2 * math.sin(weather.clock / 170) or 1) or 0
        weather.rain = weather.rain + math.clamp(target - weather.rain, -dt / RAIN_FADE, dt / RAIN_FADE)
        local hour = (START_HOUR + clockSeconds / DAY_SECONDS * 24) % 24
        tickSkies(dt, hour)
        local blow = weather.rain >= STORM_RAIN and WIND_STORM or weather.rain > 0.3 and WIND_RAIN or WIND_FAIR
        weather.wind = weather.wind + (blow - weather.wind) * math.min(1, dt / WIND_EASE)
        weather.windDir = weather.windDir + (weatherRandom() - 0.5) * 0.004 -- veers slowly
        climate.rain = weather.rain
        if weather.rain > 0.3 then
            climate.dampUntil = os.clock() + DAMP_AFTER
            if next(fires) then
                douseFires() -- no fire lives in the rain
            end
        end
        weather.beat = weather.beat + dt
        if weather.beat < 0.5 then
            return
        end
        local step = weather.beat
        weather.beat = 0
        clockPart:SetAttribute("Rain", math.floor(weather.rain * 20 + 0.5) / 20)
        clockPart:SetAttribute("Fog", math.floor(weather.fog * 20 + 0.5) / 20)
        clockPart:SetAttribute("WindX", math.floor(math.cos(weather.windDir) * weather.wind * 100 + 0.5) / 100)
        clockPart:SetAttribute("WindZ", math.floor(math.sin(weather.windDir) * weather.wind * 100 + 0.5) / 100)
        local night = hour >= NIGHT_FROM or hour < NIGHT_TO
        for _, player in ipairs(Players:GetPlayers()) do
            local hrp = player.Name ~= SKY_PLAYER and getHumanoidRootPart(player)
            local s = hrp and surviving[player]
            if s then
                local shelter = shelterOf(player, hrp)
                local inRain = weather.rain > 0.3 and shelter == ""
                local byFire = false
                for fire in pairs(fires) do
                    local d = fire.Position - hrp.Position
                    if Vector3.new(d.X, 0, d.Z).Magnitude <= WARM_RANGE then
                        byFire = true
                    end
                end
                s.wet = math.clamp((s.wet or 0) + (inRain and step * 100 / WET_SECONDS
                    or -step * 100 / DRY_SECONDS * (byFire and FIRE_DRIES or 1)), 0, 100)
                s.cold = not (byFire or shelter == "enclosed") and (night or (inRain and s.wet >= 50))
                if player:GetAttribute("InRain") ~= inRain then
                    player:SetAttribute("InRain", inRain)
                    player:SetAttribute("RainPace", inRain and RAIN_PACE or 1)
                    setCarryPace(player, heldBlocksByPlayer[player])
                end
                player:SetAttribute("Wet", math.floor(s.wet + 0.5))
                player:SetAttribute("Cold", s.cold)
                player:SetAttribute("Sheltered", shelter)
            end
        end
    end

    return tickWeather
end)()

-- The volleyball that washed up with the raft, as Wilson did. It has no name: Godling may give it one.
if not findWorkspaceChild("Volleyball") then
    createPiece("Volleyball", CFrame.new(Vector3.new(ISLAND.volleyball[1], 0.6, ISLAND.volleyball[2])),
        Vector3.new(1.1, 1.1, 1.1), Color3.fromRGB(245, 242, 232), "Volleyball", woodPhysics, ART.Volleyball,
        Enum.PartType.Ball)
end

local function strike(player, inputData)
    local hrp = getHumanoidRootPart(player)
    local held = heldBlocksByPlayer[player]
    local tool = held and held:GetAttribute("ToolKind")
    if not hrp or not tool then
        player:SetAttribute("LastActionResult", "StrikeFailed:NoTool")
        return
    end
    local target = inputData and inputData.name and findWorkspaceChild(tostring(inputData.name))
    if not target or not target:IsA("BasePart") then
        player:SetAttribute("LastActionResult", "StrikeFailed:NoTarget")
        return
    end
    local body = hrp.Position
    local nearest = nearestPoint(target, body)
    if (nearest - body).Magnitude > STRIKE_RANGE then
        player:SetAttribute("LastActionResult", "StrikeFailed:OutOfRange")
        return
    end
    if os.clock() - (lastStrikeAt[player] or -math.huge) < STRIKE_COOLDOWN then
        player:SetAttribute("LastActionResult", "StrikeFailed:TooSoon")
        return
    end
    lastStrikeAt[player] = os.clock()
    player:SetAttribute("Strikes", (player:GetAttribute("Strikes") or 0) + 1) -- the renderer plays the swing
    local role = target:GetAttribute("RenderRole")
    local result
    if target.Name == QUARRY.name and tool == "Hammer" then
        result = breakStone(target, body, nearest)
    elseif role == "Tree" and tool == "Axe" then
        result = chopTree(target, body)
    elseif target:GetAttribute("Fastened") and tool == "Hammer" then
        result = unfasten(target)
    elseif role == "Log" and tool == "Axe" and not target:GetAttribute("Fastened") and not isCarried(target) then
        result = carveLog(target)
    elseif role == "Fish" and tool == "Spear" then
        result = catchFish(target, body)
    elseif role == "Log" and tool == "Spear" and not isCarried(target) then
        result = rubLog(target) -- a stick worked against the wood: the way to fire
    else
        result = "StrikeNoEffect:" .. tool
    end
    local rubbing = role == "Log" and tool == "Spear"
    gesture(player, rubbing and "Kindle" or tool == "Spear" and "Spear" or tool == "Hammer" and "Mine"
        or role == "Log" and "Carve" or "Chop")
    player:SetAttribute("LastActionResult", result)
end

local lastFastenAt = {}

local function isPlacing(piece)
    for _, p in ipairs(placingBlocks) do
        if p.block == piece then
            return true
        end
    end
    return false
end

-- Pieces settle and hold (ADR-005), as blocks do in Minecraft. A block or log that has come to rest lying on a face
-- is squared into its grid cell and held there (anchored), so the body can no longer shove stacks, walls and beams
-- askew. Lifting a piece wakes whatever rested on it, which falls until it settles again.
local SETTLE_FLAT = math.cos(math.rad(4)) -- one of its own axes stands this straight up: it lies on a face
local SETTLE_PASSES = 2 -- still for this many passes in a row (0.5 s apart) before it settles
local restPasses = {}

local function dot(a, b)
    return a.X * b.X + a.Y * b.Y + a.Z * b.Z
end

local function wouldOverlap(piece, cframe) -- touching is fine: the probe is a little smaller than the piece
    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { piece }
    local probe = Instance.new("Part")
    probe.Size = piece.Size - Vector3.new(0.2, 0.2, 0.2)
    probe.CFrame = cframe
    local hits = Workspace:GetPartsInPart(probe, params)
    probe:Destroy()
    for _, hit in ipairs(hits) do
        if isSolid(hit) then
            return true
        end
    end
    return false
end

-- The rotation `cf` has, squared to the nearest quarter turns; nil if the piece leans or stands on an edge.
local function squaredRotation(cf)
    local vertical, lying = 0, nil
    for _, axis in ipairs({ cf.RightVector, cf.UpVector, cf.LookVector }) do
        vertical = math.max(vertical, math.abs(axis.Y))
        if not lying or math.abs(axis.Y) < math.abs(lying.Y) then
            lying = axis
        end
    end
    if vertical < SETTLE_FLAT then
        return nil
    end
    -- Turn it about the vertical until a lying axis runs along the grid, then round off what tilt is left.
    local q = math.pi / 2
    local heading = math.atan2(lying.Z, lying.X)
    local off = heading - math.floor(heading / q + 0.5) * q
    local rotation = cf - cf.Position
    for _, turn in ipairs({ off, -off }) do
        local rx, ry, rz = (CFrame.fromOrientation(0, turn, 0) * rotation):ToOrientation()
        local square = CFrame.fromOrientation(math.floor(rx / q + 0.5) * q, math.floor(ry / q + 0.5) * q,
            math.floor(rz / q + 0.5) * q)
        if dot(square.RightVector, cf.RightVector) > 0.69 and dot(square.UpVector, cf.UpVector) > 0.69
            and dot(square.LookVector, cf.LookVector) > 0.69 then
            return square
        end
    end
    return nil
end

local function settle(piece)
    -- Blocks and logs square into their cell; a boulder is round and just holds where it came to rest.
    local square = SNAPPED_ROLES[piece:GetAttribute("RenderRole")] and squaredRotation(piece.CFrame)
    if square then
        local p = piece.Position
        local inCell = Vector3.new(math.floor(p.X / GRID + 0.5) * GRID, p.Y, math.floor(p.Z / GRID + 0.5) * GRID)
        for _, target in ipairs({ CFrame.new(inCell) * square, CFrame.new(p) * square }) do -- its cell, else where it lies
            if not wouldOverlap(piece, target) then
                piece.CFrame = target
                break
            end
        end
    end
    piece.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    piece.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    piece.Anchored = true
    piece:SetAttribute("Settled", true)
end

local function settleResting()
    for _, piece in ipairs(Workspace:GetChildren()) do
        local role = piece:IsA("BasePart") and piece:GetAttribute("RenderRole")
        -- Boulders too: a ball has nothing to stop it rolling, so one nudge sent a boulder across the island and
        -- into the sea, and it came back at home ("boulders travel in jumps", run n7).
        if role and (SNAPPED_ROLES[role] or role == "Boulder") and not piece.Anchored
            and not isCarried(piece) and not isPlacing(piece)
            and not piece:GetAttribute("Quaking") then -- the shaking holds nothing still: it settles after
            if piece.AssemblyLinearVelocity.Magnitude < 0.1 and piece.AssemblyAngularVelocity.Magnitude < 0.1 then
                restPasses[piece] = (restPasses[piece] or 0) + 1
                if restPasses[piece] >= SETTLE_PASSES then
                    restPasses[piece] = nil
                    settle(piece)
                end
            else
                restPasses[piece] = nil
            end
        end
    end
end

-- Lifting a piece wakes what rested on it, and what rested on that: they fall until they settle again.
wakeRestingOn = function(piece, seen)
    seen = seen or { [piece] = true }
    local c, e = piece.Position, halfExtents(piece)
    for _, other in ipairs(Workspace:GetChildren()) do
        if not seen[other] and other:IsA("BasePart") and other:GetAttribute("Settled") then
            local oc, oe = other.Position, halfExtents(other)
            if math.abs((oc.Y - oe.Y) - (c.Y + e.Y)) < 0.3 and math.abs(c.X - oc.X) < e.X + oe.X - 0.05
                and math.abs(c.Z - oc.Z) < e.Z + oe.Z - 0.05 then
                seen[other] = true
                other.Anchored = false
                other:SetAttribute("Settled", false)
                restPasses[other] = nil
                wakeRestingOn(other, seen)
            end
        end
    end
end

local function fasten(player, inputData)
    local hrp = getHumanoidRootPart(player)
    local piece = inputData and inputData.name and findWorkspaceChild(tostring(inputData.name))
    if not hrp or not piece or not piece:IsA("BasePart") or not piece:GetAttribute("IsPickupObject")
        or piece:GetAttribute("ToolKind") then
        player:SetAttribute("LastActionResult", "FastenFailed:NotAPiece")
        return
    end
    if isCarried(piece) or isPlacing(piece) then
        player:SetAttribute("LastActionResult", "FastenFailed:NotSetDown")
        return
    end
    if (nearestPoint(piece, hrp.Position) - hrp.Position).Magnitude > PLACE_RANGE then
        player:SetAttribute("LastActionResult", "FastenFailed:OutOfRange")
        return
    end
    if os.clock() - (lastFastenAt[player] or -math.huge) < FASTEN_COOLDOWN then
        player:SetAttribute("LastActionResult", "FastenFailed:TooSoon")
        return
    end
    lastFastenAt[player] = os.clock()
    -- Fastened, a piece is fixed where it is, like mortar: unlike a settled piece it stays even when what it rests on
    -- is taken away, and it cannot be lifted until a hammer knocks it loose. Nothing is welded: a weld to an anchored
    -- part made the engine move that part, and the island sank (night run n).
    local c, e = piece.Position, halfExtents(piece)
    local touching = false
    for _, other in ipairs(Workspace:GetChildren()) do
        if other ~= piece and isSolid(other) and not isCarried(other) then
            local oc, oe = other.Position, halfExtents(other)
            if math.abs(c.X - oc.X) <= e.X + oe.X + 0.08 and math.abs(c.Y - oc.Y) <= e.Y + oe.Y + 0.08
                and math.abs(c.Z - oc.Z) <= e.Z + oe.Z + 0.08 then
                touching = true
                break
            end
        end
    end
    if not touching then
        player:SetAttribute("LastActionResult", "FastenFailed:NothingTouching")
        return
    end
    if not piece.Anchored then
        settle(piece) -- squared into its cell first
    end
    piece:SetAttribute("Settled", false)
    piece:SetAttribute("Fastened", true)
    player:SetAttribute("Reaches", (player:GetAttribute("Reaches") or 0) + 1)
    gesture(player, "Fasten")
    player:SetAttribute("LastActionResult", "FastenSuccess:fixed")
end

local climbers = {} -- player -> { path = {Vector3...}, times = {seconds per leg}, leg, t }

-- Is there room for a standing body at `spot` with its feet at `feetY`? Nothing solid but the ladder in the way.
local function bodyFits(player, spot, feetY, ladder)
    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { ladder, player.Character }
    local probe = Instance.new("Part")
    probe.Size = Vector3.new(1.9, 4.6, 1.9)
    probe.CFrame = CFrame.new(Vector3.new(spot.X, feetY + 0.2 + 2.3, spot.Z))
    local hits = Workspace:GetPartsInPart(probe, params)
    probe:Destroy()
    for _, hit in ipairs(hits) do
        if isSolid(hit) then
            return false
        end
    end
    return true
end

local function climb(player, inputData)
    local hrp = getHumanoidRootPart(player)
    local ladder = inputData and inputData.name and findWorkspaceChild(tostring(inputData.name))
    if not hrp or not ladder or ladder:GetAttribute("RenderRole") ~= "Ladder" then
        player:SetAttribute("LastActionResult", "ClimbFailed:NoLadder")
        return
    end
    if not ladder.Anchored or isCarried(ladder) then
        player:SetAttribute("LastActionResult", "ClimbFailed:NotSetUp")
        return
    end
    if climbers[player] then
        player:SetAttribute("LastActionResult", "ClimbFailed:AlreadyClimbing")
        return
    end
    local body = hrp.Position
    local feet = body.Y - BODY_ABOVE_FEET
    local lp = ladder.Position
    if Vector3.new(body.X - lp.X, 0, body.Z - lp.Z).Magnitude > 2.8 then
        player:SetAttribute("LastActionResult", "ClimbFailed:TooFar")
        return
    end
    local bottom, top = lp.Y - LADDER_SIZE.Y / 2, lp.Y + LADDER_SIZE.Y / 2
    local face = ladder.CFrame.LookVector
    face = Vector3.new(face.X, 0, face.Z).Unit
    -- At its foot: up. Standing on something higher, anywhere along its height (a ladder may be taller than the
    -- wall it stands against): down.
    local up = math.abs(feet - bottom) < 1.2
    if not up and (feet < bottom + 0.9 or feet > top + 0.6) then
        player:SetAttribute("LastActionResult", "ClimbFailed:NotAtAnEnd")
        return
    end
    -- Step off on whichever side of the ladder has a surface at the far end and room for the whole body: going up,
    -- the highest surface the ladder reaches (at least a body's step above its foot); going down, the ground or floor
    -- at its foot. Without the room check, climbing down beside a block dropped the body half inside it, wedged
    -- between block and ladder (test run t1).
    local best, bestTop = nil, nil
    for _, reach in ipairs({ 1.5, 2.2 }) do -- clear of the ladder for a 2-wide body; a little further if that is taken
        for _, sign in ipairs({ 1, -1 }) do
            local spot = Vector3.new(lp.X, 0, lp.Z) + face * (sign * reach)
            local found = up and surfaceTopAt(spot.X, spot.Z, bottom + 0.9, top + 0.5, ladder)
                or surfaceTopAt(spot.X, spot.Z, bottom - 1.2, bottom + 0.6, ladder)
            if found and (bestTop == nil or (up and found > bestTop) or (not up and found < bestTop))
                and bodyFits(player, spot, found, ladder) then
                best, bestTop = spot, found
            end
        end
    end
    if not best then
        player:SetAttribute("LastActionResult", up and "ClimbFailed:NothingAtTop" or "ClimbFailed:NothingAtBottom")
        return
    end
    -- Up the side the body stands on; down the side it steps off to, not through what it stood on.
    local side = up and Vector3.new(body.X - lp.X, 0, body.Z - lp.Z) or Vector3.new(best.X - lp.X, 0, best.Z - lp.Z)
    local onLadder = Vector3.new(lp.X, 0, lp.Z) + (side.Magnitude > 0.01 and side.Unit or face) * 1.2
    local endY = bestTop + BODY_ABOVE_FEET
    local path = { body, Vector3.new(onLadder.X, body.Y, onLadder.Z), Vector3.new(onLadder.X, endY + 0.3, onLadder.Z),
        Vector3.new(best.X, endY, best.Z) }
    local times = { 0.3, math.abs(endY + 0.3 - body.Y) / CLIMB_SPEED, 0.5 }
    local humanoid = getHumanoid(player)
    if humanoid then
        humanoid:CancelMoveTo()
    end
    hrp.Anchored = true
    climbers[player] = { path = path, times = times, leg = 1, t = 0 }
    player:SetAttribute("Climbing", true)
    player:SetAttribute("LastActionResult", string.format("ClimbStarted:%s:%.1f", up and "up" or "down",
        times[1] + times[2] + times[3]))
end

-- Drawing in the sand (the user's wish, after Cast Away, where Chuck's first act is to write HELP on the beach with
-- his foot). Godling drags a foot from where it stands to a point and the world leaves a groove, on open sand only:
-- not on grass, rock or under a tree. Each groove keeps its two ends (attribute Stroke), so the mind can read back
-- what it wrote. The grooves stay.
local MARK_WIDTH, MARK_MAX_LENGTH, MARK_MAX = 0.7, 20, 400
local markCount = 0

local function onOpenSand(x, z)
    local sand = false
    for _, g in ipairs(groundParts) do
        if math.abs(x - g.pos[1]) <= g.size[1] / 2 and math.abs(z - g.pos[3]) <= g.size[3] / 2 then
            if not g.sand then
                return false -- grass lies over the sand here
            end
            sand = true
        end
    end
    if not sand then
        return false -- the sea
    end
    for _, group in ipairs({ mesas, trees }) do
        for _, m in ipairs(group) do
            if math.abs(x - m.pos[1]) <= m.size[1] / 2 and math.abs(z - m.pos[3]) <= m.size[3] / 2 then
                return false
            end
        end
    end
    return true
end

local function drawLine(player, inputData)
    local hrp = getHumanoidRootPart(player)
    local to = inputData and inputData.to
    if not hrp or type(to) ~= "table" or not tonumber(to[1]) or not tonumber(to[2]) then
        player:SetAttribute("LastActionResult", "DrawFailed:BadTarget")
        return
    end
    local x1, z1 = hrp.Position.X, hrp.Position.Z
    local x2, z2 = tonumber(to[1]), tonumber(to[2])
    local length = math.sqrt((x2 - x1) ^ 2 + (z2 - z1) ^ 2)
    if length < 0.5 or length > MARK_MAX_LENGTH then
        player:SetAttribute("LastActionResult", "DrawFailed:Length")
        return
    end
    if markCount >= MARK_MAX then
        player:SetAttribute("LastActionResult", "DrawFailed:BeachFull")
        return
    end
    local steps = math.ceil(length / 0.5)
    for k = 0, steps do
        if not onOpenSand(x1 + (x2 - x1) * k / steps, z1 + (z2 - z1) * k / steps) then
            player:SetAttribute("LastActionResult", "DrawFailed:NotSand")
            return
        end
    end
    markCount = markCount + 1
    local mark = Instance.new("Part")
    mark.Name = "Mark_" .. markCount
    mark.Size = Vector3.new(length + MARK_WIDTH, 0.06, MARK_WIDTH)
    -- fromOrientation(0, yaw, 0) turns the part's length (X) to (cos yaw, 0, -sin yaw): along the stroke.
    mark.CFrame = CFrame.new(Vector3.new((x1 + x2) / 2, -SAND_DROP + 0.03, (z1 + z2) / 2))
        * CFrame.fromOrientation(0, math.atan2(-(z2 - z1), x2 - x1), 0)
    mark.Anchored = true
    mark.CanCollide = false
    mark.Color = Color3.fromRGB(176, 150, 102)
    mark:SetAttribute("RenderRole", "SandMark")
    mark:SetAttribute("Stroke", string.format("%.1f,%.1f,%.1f,%.1f", x1, z1, x2, z2))
    mark.Parent = Workspace
    gesture(player, "Draw")
    player:SetAttribute("LastActionResult", "DrawSuccess:" .. mark.Name)
end

local function advanceClimbers(dt)
    for player, c in pairs(climbers) do
        local hrp = getHumanoidRootPart(player)
        if not hrp then
            climbers[player] = nil
        else
            c.t = c.t + dt
            while c.leg <= #c.times and c.t >= c.times[c.leg] do
                c.t = c.t - c.times[c.leg]
                c.leg = c.leg + 1
            end
            if c.leg > #c.times then
                hrp.CFrame = CFrame.new(c.path[#c.path]) * (hrp.CFrame - hrp.CFrame.Position)
                hrp.Anchored = false
                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                climbers[player] = nil
                player:SetAttribute("Climbing", false)
            else
                local a, b = c.path[c.leg], c.path[c.leg + 1]
                local alpha = c.times[c.leg] > 0 and c.t / c.times[c.leg] or 1
                hrp.CFrame = CFrame.new(a + (b - a) * alpha) * (hrp.CFrame - hrp.CFrame.Position)
            end
        end
    end
end

-- One table for the sky's parts, to spare the main chunk's locals (Luau allows 200, and the script is at the limit):
-- turners (player -> the yaw Face is turning the body to), power (the guest panel's powers, with the sky events
-- below) and quake (the earthquake, after the sky events: start, tick, and Brace for a body).
local sky = { turners = {} }
local stepBody -- by freeTrappedBodies below: stepping up onto, or down off, something a block high

local function yawOf(cframe) -- the way a part faces, as the yaw the engine gives a walking body (forward is -Z)
    local look = cframe.LookVector
    return math.atan2(-look.X, -look.Z)
end

local function face(player, inputData)
    local hrp = getHumanoidRootPart(player)
    local target = inputData and inputData.position and parsePosition(inputData.position)
    if not hrp or not target then
        player:SetAttribute("LastActionResult", "FaceFailed:InvalidPosition")
        return
    end
    if climbers[player] then
        player:SetAttribute("LastActionResult", "FaceFailed:Climbing")
        return
    end
    local dx, dz = target.X - hrp.Position.X, target.Z - hrp.Position.Z
    if dx * dx + dz * dz < 0.01 then
        player:SetAttribute("LastActionResult", "FaceFailed:TooClose")
        return
    end
    local humanoid = getHumanoid(player)
    if humanoid then
        humanoid:CancelMoveTo()
    end
    sky.turners[player] = math.atan2(-dx, -dz)
    player:SetAttribute("LastActionResult", "FaceStarted")
end

local function advanceTurners(dt)
    for player, target in pairs(sky.turners) do
        local hrp = getHumanoidRootPart(player)
        if not hrp or climbers[player] then
            sky.turners[player] = nil
        else
            local now = yawOf(hrp.CFrame)
            local delta = (target - now + math.pi) % (2 * math.pi) - math.pi
            local step = math.clamp(delta, -TURN_RATE * dt, TURN_RATE * dt)
            hrp.CFrame = CFrame.new(hrp.Position) * CFrame.fromOrientation(0, now + step, 0)
            if math.abs(delta) <= TURN_RATE * dt then
                sky.turners[player] = nil
            end
        end
    end
end

if AgentInputService then
    AgentInputService.InputReceived:Connect(function(player, inputType, inputData)
        local humanoid = getHumanoid(player)
        if not humanoid then return end

        if inputType == "MoveTo" and inputData and inputData.position then
            local targetPosition = parsePosition(inputData.position)
            if not targetPosition then
                player:SetAttribute("LastActionResult", "MoveToFailed:InvalidPosition")
                return
            end
            sky.turners[player] = nil -- walking turns the body itself
            humanoid:MoveTo(targetPosition)
        elseif inputType == "Face" then
            face(player, inputData)
        elseif inputType == "Sky" then
            sky.power(player, inputData)
        elseif inputType == "Stop" then
            humanoid:CancelMoveTo()
        elseif inputType == "Jump" then
            humanoid.Jump = true
        elseif inputType == "Pickup" then
            pickupBlock(player, inputData)
        elseif inputType == "Place" then
            placeBlock(player, inputData)
        elseif inputType == "Throw" then
            throwBlock(player, inputData)
        elseif inputType == "Strike" then
            strike(player, inputData)
        elseif inputType == "Fasten" then
            fasten(player, inputData)
        elseif inputType == "Climb" then
            climb(player, inputData)
        elseif inputType == "Draw" then
            drawLine(player, inputData)
        elseif inputType == "Shake" then
            shakePalm(player, inputData)
        elseif inputType == "Eat" then
            eat(player)
        elseif inputType == "Talk" then -- the mind spoke (world chat): the body talks along
            gesture(player, "Talk")
            player:SetAttribute("LastActionResult", "TalkSuccess")
        elseif inputType == "Think" then
            think(player, inputData)
        elseif inputType == "StepUp" then
            stepBody(player, inputData, false)
        elseif inputType == "StepDown" then
            stepBody(player, inputData, true)
        elseif inputType == "Cook" then
            cook(player)
        elseif inputType == "Brace" then -- crouch and hold on while the ground shakes (the body's own reflex)
            sky.quake.brace(player)
        else
            player:SetAttribute("LastActionResult", "InvalidAction")
        end
    end)
end

--------------------------------------------------------------------------------
-- SUPPLY (Godling, ADR-003 O7)
--------------------------------------------------------------------------------

local supplyState = SUPPLY_SEED
local supplyCounter = 0
local supplyTimer = 0
local keepsakeTimer = 0
local settleTimer = 0

local function supplyRandom()
    -- Park-Miller: small enough to stay exact in doubles, so every run gets the same sequence.
    supplyState = (supplyState * 16807) % 2147483647
    return supplyState / 2147483647
end

local function within(x, z, def, margin)
    return math.abs(x - def.pos[1]) < def.size[1] / 2 + margin and math.abs(z - def.pos[3]) < def.size[3] / 2 + margin
end

local function isHeld(part)
    for _, held in pairs(heldBlocksByPlayer) do
        if held == part then
            return true
        end
    end
    return false
end

local function looseGroundCubes()
    local count = 0
    for _, inst in ipairs(Workspace:GetChildren()) do
        if inst:IsA("Part") and inst:GetAttribute("RenderRole") == "PickupObject" and not isHeld(inst)
            and math.abs(inst.Position.Y - BLOCK_SIZE / 2) < 0.15 then
            count = count + 1
        end
    end
    return count
end

local function clearSupplySpot(x, z)
    -- Well inside the island, away from the shore: land 3 units out every way. (Inside one ground part with a margin
    -- worked on the old island; the castaway island's ground is many narrow strips, so no spot ever qualified.)
    if not (overLand(x, z) and overLand(x + 3, z) and overLand(x - 3, z) and overLand(x, z + 3) and overLand(x, z - 3)) then
        return false
    end
    for _, m in ipairs(mesas) do
        if within(x, z, m, 2.5) then -- not on a mesa and not against its foot
            return false
        end
    end
    for _, t in ipairs(trees) do
        if within(x, z, t, 2.5) then -- not into a tree's crown
            return false
        end
    end
    if within(x, z, QUARRY, 2.5) then
        return false
    end
    for _, inst in ipairs(Workspace:GetChildren()) do
        if inst:IsA("Part") and inst:GetAttribute("IsPickupObject") then
            local dx, dz = inst.Position.X - x, inst.Position.Z - z
            if dx * dx + dz * dz < 4 then
                return false
            end
        end
    end
    for _, player in ipairs(Players:GetPlayers()) do
        local hrp = getHumanoidRootPart(player)
        if hrp then
            local dx, dz = hrp.Position.X - x, hrp.Position.Z - z
            if dx * dx + dz * dz < 9 then
                return false
            end
        end
    end
    return true
end

local function deliverCube()
    for _ = 1, 40 do
        local x = -60 + supplyRandom() * 115
        local z = -62 + supplyRandom() * 124
        if clearSupplySpot(x, z) then
            supplyCounter = supplyCounter + 1
            createBlock("SupplyBlock_" .. supplyCounter, Vector3.new(x, SUPPLY_DROP_HEIGHT, z), "Sand")
            return
        end
    end
end

--------------------------------------------------------------------------------
-- SKY EVENTS (Godling: a stone falls from the sky, announced by its shadow)
--------------------------------------------------------------------------------

local skyState = SUPPLY_SEED + 1 -- its own fixed sequence, so the supply drops stay as they were
local skyCounter = 0
local skyTimer = 0
local skyFalls = {} -- { n, x, z, shadow, landsAt }

local function skyRandom()
    skyState = (skyState * 16807) % 2147483647
    return skyState / 2147483647
end

local function clearOfPieces(x, z, clearance)
    for _, inst in ipairs(Workspace:GetChildren()) do
        if inst:IsA("Part") and inst:GetAttribute("IsPickupObject") then
            local dx, dz = inst.Position.X - x, inst.Position.Z - z
            if dx * dx + dz * dz < clearance * clearance then
                return false
            end
        end
    end
    return true
end

local function skySpotNear(player)
    local hrp = getHumanoidRootPart(player)
    if not hrp then
        return nil
    end
    for _ = 1, 40 do
        local angle = skyRandom() * 2 * math.pi
        local dist = SKY_SPOT_NEAR + skyRandom() * (SKY_SPOT_FAR - SKY_SPOT_NEAR)
        local x, z = hrp.Position.X + math.cos(angle) * dist, hrp.Position.Z + math.sin(angle) * dist
        if clearSupplySpot(x, z) and clearOfPieces(x, z, SKY_SPOT_CLEARANCE) then
            return x, z
        end
    end
    return nil
end

local skyFlashes = {} -- { part, gone }

local function skyMark(kind, id)
    return function(part)
        part:SetAttribute("SkyEvent", kind)
        part:SetAttribute("SkyId", id)
    end
end

local function skyMarker(name, size, position, color, role) -- a shadow or a bolt: seen, never touched
    local part = Instance.new("Part")
    part.Name = name
    part.Size = size
    part.Position = position
    part.Anchored = true
    part.CanCollide = false
    part.Color = color
    part:SetAttribute("RenderRole", role)
    part.Parent = Workspace
    return part
end

local function godlingPlayer() -- the one the sky aims for: the first player that is not the guest panel
    for _, player in ipairs(Players:GetPlayers()) do
        if player.Name ~= SKY_PLAYER then
            return player
        end
    end
    return nil
end

local function shadowOccupied(fall) -- the sky never drops a stone on someone: it waits until the shadow is clear
    for _, player in ipairs(Players:GetPlayers()) do
        local hrp = player.Name ~= SKY_PLAYER and getHumanoidRootPart(player)
        if hrp then
            local dx, dz = hrp.Position.X - fall.x, hrp.Position.Z - fall.z
            if dx * dx + dz * dz < SKY_SHADOW_CLEARANCE * SKY_SHADOW_CLEARANCE then
                return true
            end
        end
    end
    return false
end

local function announceSkyFall(x, z)
    skyCounter = skyCounter + 1
    local shadow = skyMarker("SkyShadow_" .. skyCounter, Vector3.new(3.2, 0.06, 3.2), Vector3.new(x, 0.04, z),
        Color3.fromRGB(24, 22, 20), "SkyShadow")
    skyMark("Meteor", skyCounter)(shadow)
    shadow:SetAttribute("LandsIn", SKY_WARN_SECONDS)
    table.insert(skyFalls, { n = skyCounter, x = x, z = z, shadow = shadow, landsAt = os.clock() + SKY_WARN_SECONDS })
    print(string.format("SKY Meteor #%d warned at (%.1f, %.1f), lands in %ds", skyCounter, x, z, SKY_WARN_SECONDS))
    return skyCounter
end

local function advanceSkyFalls()
    local now = os.clock()
    local i = 1
    while i <= #skyFalls do
        local fall = skyFalls[i]
        if now >= fall.landsAt and not shadowOccupied(fall) then
            fall.shadow:Destroy()
            local size = Vector3.new(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE)
            local stone = createPiece("Meteor_" .. fall.n, CFrame.new(fall.x, SKY_DROP_HEIGHT, fall.z), size,
                Color3.fromRGB(64, 56, 52), "Stone", stonePhysics) -- dark and bare: not a quarried stone
            skyMark("Meteor", fall.n)(stone)
            stone.AssemblyLinearVelocity = Vector3.new(0, -SKY_FALL_SPEED, 0)
            hurtNear(fall.x, fall.z, HARM.meteorRange, HARM.meteor, "Meteor") -- it is down in about a second
            print(string.format("SKY Meteor #%d landed at (%.1f, %.1f)", fall.n, fall.x, fall.z))
            table.remove(skyFalls, i)
        else
            local left = math.max(0, math.ceil(fall.landsAt - now)) -- 0 while it waits for a clear shadow
            if fall.shadow:GetAttribute("LandsIn") ~= left then
                fall.shadow:SetAttribute("LandsIn", left)
            end
            i = i + 1
        end
    end
    i = 1
    while i <= #skyFlashes do
        if now >= skyFlashes[i].gone then
            skyFlashes[i].part:Destroy()
            table.remove(skyFlashes, i)
        else
            i = i + 1
        end
    end
end

local function nearestTree(role, to)
    local best, bestDist = nil, math.huge
    for _, t in ipairs(trees) do
        local part = t.part
        if part and part.Parent and part:GetAttribute("RenderRole") == role then
            local d = (Vector3.new(part.Position.X, 0, part.Position.Z) - Vector3.new(to.X, 0, to.Z)).Magnitude
            if d < bestDist then
                best, bestDist = t, d
            end
        end
    end
    return best
end

-- Lightning strikes standing tree `t`: a bolt, the tree felled into logs, and hurt for anyone close. From the guest
-- panel's Lightning power, and from the storms in heavy rain (WEATHER).
local function lightningOn(t, from)
    skyCounter = skyCounter + 1
    local p = t.part.Position
    local bolt = skyMarker("SkyBolt_" .. skyCounter, Vector3.new(0.35, 30, 0.35), Vector3.new(p.X, 15, p.Z),
        Color3.fromRGB(255, 244, 170), "SkyFlash")
    table.insert(skyFlashes, { part = bolt, gone = os.clock() + SKY_FLASH_SECONDS })
    local mark = skyMark("Lightning", skyCounter)
    local names = fellTree(t.part, from, function(log)
        mark(log)
        log:SetAttribute("FromTree", t.name)
    end)
    hurtNear(p.X, p.Z, HARM.lightningRange, HARM.lightning, "Lightning")
    print(string.format("SKY Lightning #%d felled %s into %s", skyCounter, t.name, table.concat(names, ",")))
    return skyCounter
end

-- A storm's lightning: a standing palm 12 to 45 from Godling, one at random (the nearest beyond 12 if none is).
stormStrike = function()
    local godling = godlingPlayer()
    local hrp = godling and getHumanoidRootPart(godling)
    if not hrp then
        return
    end
    local near, beyond = {}, nil
    for _, t in ipairs(trees) do
        local part = t.part
        if part and part.Parent and part:GetAttribute("RenderRole") == "Tree" then
            local d = (Vector3.new(part.Position.X, 0, part.Position.Z) - Vector3.new(hrp.Position.X, 0, hrp.Position.Z))
                .Magnitude
            if d >= 12 and d <= 45 then
                table.insert(near, t)
            elseif d > 45 and (beyond == nil or d < beyond[2]) then
                beyond = { t, d }
            end
        end
    end
    local t = #near > 0 and near[math.random(1, #near)] or (beyond and beyond[1])
    if t then
        lightningOn(t, hrp.Position)
    end
end

-- A ship passes far out at sea now and then, as one did in the film (ADR-010): the first 1 to 2 hours into a run, then
-- every 2.5 to 5 hours. It sails along the horizon for five minutes and is gone. Nothing comes of it (yet).
local tickShip = (function() -- a function of its own, so its locals stay out of the main chunk's 200 (Luau's limit)
    local SHIP_FIRST_MIN, SHIP_FIRST_MAX, SHIP_GAP_MIN, SHIP_GAP_MAX = 60 * 60, 120 * 60, 150 * 60, 300 * 60
    local SHIP_OUT, SHIP_RUN, SHIP_SECONDS = 215, 260, 300 -- how far out, how far it sails, in how long
    local AWAY_FROM = math.atan2(-154, 186) -- where the islet lies (tools/make_island.py ISLET), not to sail across it
    local due = SHIP_FIRST_MIN + math.random() * (SHIP_FIRST_MAX - SHIP_FIRST_MIN)
    local clock, ship = 0, nil
    local LOOK = { -- name, size, offset along the hull (x) and up (y), colour
        { "Ship", Vector3.new(14, 3, 4.5), 0, 0, Color3.fromRGB(70, 52, 40) },
        { "Ship_Cabin", Vector3.new(5, 3, 3.6), -3, 3, Color3.fromRGB(232, 228, 216) },
        { "Ship_Mast", Vector3.new(0.5, 12, 0.5), 2, 7.5, Color3.fromRGB(60, 45, 35) },
        { "Ship_Sail", Vector3.new(6, 8, 0.25), 2.5, 8.5, Color3.fromRGB(240, 236, 224) },
    }

    local function place(t)
        local along = (t / SHIP_SECONDS - 0.5) * SHIP_RUN
        local centre = Vector3.new(math.cos(ship.a), 0, math.sin(ship.a)) * SHIP_OUT + ship.dir * along
        local turn = CFrame.fromOrientation(0, math.atan2(-ship.dir.Z, ship.dir.X), 0) -- the hull's length along its way
        for i, look in ipairs(LOOK) do
            ship.parts[i].CFrame = CFrame.new(centre + Vector3.new(0, OCEAN_TOP_Y + 1.2 + look[4], 0)) * turn
                * CFrame.new(look[3], 0, 0)
        end
    end

    local function tickShip(dt)
        clock = clock + dt
        if not ship and clock >= due then
            local a
            repeat -- anywhere round the island but where the islet lies
                a = math.random() * 2 * math.pi
            until math.abs(math.atan2(math.sin(a - AWAY_FROM), math.cos(a - AWAY_FROM))) > math.rad(50)
            local dir = Vector3.new(-math.sin(a), 0, math.cos(a)) * (math.random() < 0.5 and 1 or -1)
            ship = { a = a, dir = dir, t = 0, parts = {} }
            for _, look in ipairs(LOOK) do
                local part = Instance.new("Part")
                part.Name, part.Size, part.Color = look[1], look[2], look[5]
                part.Anchored, part.CanCollide = true, false
                part.Parent = Workspace
                table.insert(ship.parts, part)
            end
            ship.parts[1]:SetAttribute("RenderRole", "Ship")
            place(0)
            print(string.format("SHIP passing at (%.0f, %.0f)", math.cos(a) * SHIP_OUT, math.sin(a) * SHIP_OUT))
        elseif ship then
            ship.t = ship.t + dt
            if ship.t >= SHIP_SECONDS then
                for _, part in ipairs(ship.parts) do
                    part:Destroy()
                end
                ship = nil
                due = clock + SHIP_GAP_MIN + math.random() * (SHIP_GAP_MAX - SHIP_GAP_MIN)
            else
                place(ship.t)
            end
        end
    end

    return tickShip
end)()

local function dropGift(kind, x, z)
    skyCounter = skyCounter + 1
    local piece
    if kind == "Stone" then
        quarryWork.made = quarryWork.made + 1 -- stones share one numbering, wherever they come from
        local size = Vector3.new(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE)
        piece = createPiece("Stone_" .. quarryWork.made, CFrame.new(x, SKY_GIFT_HEIGHT, z), size,
            Color3.fromRGB(150, 146, 140), "Stone", stonePhysics, ART.Stone)
    else
        logCounter = logCounter + 1
        piece = createPiece("Log_" .. logCounter, CFrame.new(x, SKY_GIFT_HEIGHT, z), LOG_SIZE,
            Color3.fromRGB(140, 98, 62), "Log", woodPhysics, ART.Log)
    end
    skyMark(kind, skyCounter)(piece)
    print(string.format("SKY %s #%d dropped %s at (%.1f, %.1f)", kind, skyCounter, piece.Name, x, z))
    return skyCounter
end

-- Driftwood (the user's choice, after run n7, where the same few logs were both firewood and building wood; ADR-010):
-- every few minutes the sea leaves a log up the beach, as wreckage washed up in the film, while fewer than DRIFT_MAX
-- lie on the sand.
local tickDriftwood = (function() -- a function of its own, as tickWeather's
    local DRIFT_EVERY, DRIFT_MAX, DRIFT_FIRST = 180, 6, 60
    local driftTimer = DRIFT_EVERY - DRIFT_FIRST
    local driftState = SUPPLY_SEED + 11

    local function driftRandom()
        driftState = (driftState * 16807) % 2147483647
        return driftState / 2147483647
    end

    local function driftwoodOnBeach()
        local n = 0
        for _, inst in ipairs(Workspace:GetChildren()) do
            if inst:IsA("BasePart") and inst:GetAttribute("Driftwood") and not isCarried(inst) and inst.Position.Y < 2.5
                and onOpenSand(inst.Position.X, inst.Position.Z) then
                n = n + 1
            end
        end
        return n
    end

    local function washUpDriftwood()
        if driftwoodOnBeach() >= DRIFT_MAX then
            return nil
        end
        for _ = 1, 30 do
            local s = SHALLOWS[1 + math.floor(driftRandom() * #SHALLOWS)]
            local length = math.sqrt(s[1] * s[1] + s[2] * s[2])
            local dx, dz = -s[1] / length, -s[2] / length -- up the beach: towards the island's middle
            local sand = nil
            for k = 1, 40 do -- from the water up the beach, while it is open sand
                local x, z = s[1] + dx * 1.25 * k, s[2] + dz * 1.25 * k
                if onOpenSand(x, z) then
                    sand = sand or k
                    if k - sand >= 2 and clearSupplySpot(x, z) then -- clear of the water's edge and of other pieces
                        logCounter = logCounter + 1
                        local along = math.abs(dx) > math.abs(dz) and 90 or 0 -- lying along the shore
                        local log = createPiece("Log_" .. logCounter, CFrame.new(x, 1.6, z)
                            * CFrame.fromOrientation(0, math.rad(along), 0), LOG_SIZE, Color3.fromRGB(150, 128, 100), "Log",
                            woodPhysics, ART.Log)
                        log:SetAttribute("Driftwood", true)
                        print(string.format("DRIFTWOOD %s washed up at (%.1f, %.1f)", log.Name, x, z))
                        return log
                    end
                elseif sand then
                    break -- past the beach
                end
            end
        end
        return nil
    end

    local function tickDriftwood(dt)
        driftTimer = driftTimer + dt
        if driftTimer >= DRIFT_EVERY then
            driftTimer = 0
            washUpDriftwood()
        end
    end

    return tickDriftwood
end)()

-- EARTHQUAKE (the user's wish: disasters that test what Godling builds, on real physics; research/god-powers-and-
-- disasters-plan.md, phase 1). A rumble warns, then the ground shakes for a while and dies away.
-- The ground itself stays still: moving hundreds of island parts would be heavy and flood the viewers' updates. Every
-- loose piece gets the ground's motion turned round instead, each tick an impulse of -a(t) x its mass x dt at its own
-- centre, which is the same physics seen from the ground. Rapier then decides what rocks, slides and falls: a thin
-- column topples, a wide wall stands, a fastened piece holds to the ground as it always does.
-- Bodies are never shaken. At the rumble a body looks around (LookAround); braced (the body's reflex, the Brace input),
-- it crouches and holds on; caught unbraced when the shaking starts, it is knocked down for a moment (Stagger) and gets
-- up (GetUp), unhurt. Nothing ever gives way under a body's feet.
-- The Clock carries Quake (0-1), QuakePhase ("rumble", "shaking", "fade", "") and QuakeId; after it, QuakeFell.
sky.quake = (function()
    local RUMBLE, SHAKE, FADE, AFTER = 8, 20, 5, 8 -- seconds: the warning, the shaking, dying away, settling
    -- Tuned against test structures (plan §5): at a peak of about 0.65 g, a loose wall loses its top row when shaken
    -- along it and most of itself when shaken across; a loose 5-high tower lost its top two in one direction of two
    -- and stood in the other. Fastened pieces never moved. Near 0.9 g loose blocks slide off each other and most of a
    -- loose wall comes down. Slow swings topple; fast ones only rattle.
    local RUMBLE_LEVEL, LEVEL = 0.15, 0.8 -- strength of the rumble and of the shaking (0-1)
    local ACCEL = 0.81 * Workspace.Gravity -- the ground's peak acceleration at strength 1 (gravity is 10 here)
    local FREQS = { { 0.45, 1.0 }, { 0.8, 0.6 }, { 1.5, 0.3 } } -- the shaking: three sines, Hz and weight
    local WEIGHT = 0 -- the weights' sum: the sines can add up to it at most
    for _, f in ipairs(FREQS) do
        WEIGHT = WEIGHT + f[2]
    end
    local REACH, MAX_WOKEN = 60, 200 -- pieces within this of Godling are shaken loose, nearest first
    local MIN_PIECES = 15 -- something worth testing must stand within reach
    local COOLDOWN = 600 -- seconds between disasters in test mode; the paid stream will allow one a day (phase 3)
    local MERCY_HEALTH, MERCY_AFTER_FAINT = 30, 900 -- no disaster while Godling is this weak, or this soon after a faint
    local KNOCKDOWN, LET_GO = 2.5, 1.5 -- seconds knocked down; seconds a braced body holds on after the shaking
    local active, lastEnded = nil, -math.huge
    local braced, knocked = {}, {} -- player -> true; player -> when it gets up
    local faints = {} -- player -> { count, at }: when it last fainted, for the mercy rule

    local function shakeable(part) -- blocks, stones and logs (boulders hold where they lie, ADR-009)
        return part:IsA("BasePart") and SNAPPED_ROLES[part:GetAttribute("RenderRole")] and not isCarried(part)
            and not isPlacing(part)
    end

    local function bodies()
        local out = {}
        for _, player in ipairs(Players:GetPlayers()) do
            local hrp = player.Name ~= SKY_PLAYER and getHumanoidRootPart(player)
            if hrp then
                out[player] = hrp
            end
        end
        return out
    end

    local function piecesNear(centre, reach)
        local out = {}
        for _, part in ipairs(Workspace:GetChildren()) do
            if shakeable(part) then
                local d = Vector3.new(part.Position.X - centre.X, 0, part.Position.Z - centre.Z).Magnitude
                if d <= reach then
                    table.insert(out, { part = part, d = d })
                end
            end
        end
        table.sort(out, function(a, b)
            return a.d < b.d
        end)
        return out
    end

    -- What holds a body up: the piece under its feet, and every piece under that one, down to the ground.
    local function underFeet(near)
        local held = {}
        local function under(part)
            local c, e = part.Position, halfExtents(part)
            for _, n in ipairs(near) do
                local o = n.part
                if not held[o] then
                    local oc, oe = o.Position, halfExtents(o)
                    if math.abs((oc.Y + oe.Y) - (c.Y - e.Y)) < 0.3 and math.abs(c.X - oc.X) < e.X + oe.X - 0.05
                        and math.abs(c.Z - oc.Z) < e.Z + oe.Z - 0.05 then
                        held[o] = true
                        under(o)
                    end
                end
            end
        end
        for _, hrp in pairs(bodies()) do
            local p, feet = hrp.Position, hrp.Position.Y - BODY_ABOVE_FEET
            for _, n in ipairs(near) do
                local o = n.part
                local oc, oe = o.Position, halfExtents(o)
                if not held[o] and math.abs(oc.Y + oe.Y - feet) < 0.4 and math.abs(p.X - oc.X) < oe.X + 1
                    and math.abs(p.Z - oc.Z) < oe.Z + 1 then
                    held[o] = true
                    under(o)
                end
            end
        end
        return held
    end

    local function wake(centre)
        local near = piecesNear(centre, REACH)
        local held = underFeet(near)
        active.woken = {}
        for _, n in ipairs(near) do
            local part = n.part
            if #active.woken >= MAX_WOKEN then
                break
            end
            if part.Anchored and not part:GetAttribute("Fastened") and not held[part] then
                part.Anchored = false
                part:SetAttribute("Settled", false)
                part:SetAttribute("Quaking", true)
                table.insert(active.woken, { part = part, from = part.Position })
            end
        end
        active.held = 0
        for _ in pairs(held) do
            active.held = active.held + 1
        end
    end

    local function strength(t)
        if t < RUMBLE then
            return RUMBLE_LEVEL * math.min(1, t / 2)
        elseif t < RUMBLE + SHAKE then
            return RUMBLE_LEVEL + (active.level - RUMBLE_LEVEL) * math.min(1, (t - RUMBLE) / 1.5)
        elseif t < RUMBLE + SHAKE + FADE then
            return active.level * (1 - (t - RUMBLE - SHAKE) / FADE)
        end
        return 0
    end

    local function phaseAt(t)
        if t < RUMBLE then
            return "rumble"
        elseif t < RUMBLE + SHAKE then
            return "shaking"
        elseif t < RUMBLE + SHAKE + FADE then
            return "fade"
        end
        return ""
    end

    local function groundAccel(t, level) -- horizontal, along a direction that slowly turns
        local along, across = 0, 0
        for i, f in ipairs(FREQS) do
            along = along + f[2] * math.sin(2 * math.pi * f[1] * t + active.phases[i])
            across = across + f[2] * math.sin(2 * math.pi * f[1] * 0.83 * t + active.phases[i] * 1.7)
        end
        local a = active.heading + 0.4 * math.sin(0.35 * t)
        local scale = level * ACCEL / WEIGHT -- the peak is level x ACCEL
        along, across = along * scale, across * scale * 0.35
        return Vector3.new(math.cos(a) * along - math.sin(a) * across, 0, math.sin(a) * along + math.cos(a) * across)
    end

    local function letGo(player)
        braced[player] = nil
        player:SetAttribute("Bracing", false)
        local hrp = getHumanoidRootPart(player)
        if hrp and not climbers[player] and not knocked[player] then
            hrp.Anchored = false
        end
    end

    local function knockDown(player, hrp)
        knocked[player] = os.clock() + KNOCKDOWN
        local humanoid = getHumanoid(player)
        if humanoid then
            humanoid:CancelMoveTo()
        end
        hrp.Anchored = true
        player:SetAttribute("KnockedDown", true)
        player:SetAttribute("KnockDowns", (player:GetAttribute("KnockDowns") or 0) + 1)
        gesture(player, "Stagger")
        print(string.format("QUAKE knocked %s down", player.Name))
    end

    local function getUp()
        for player, at in pairs(knocked) do
            if os.clock() >= at then
                knocked[player] = nil
                player:SetAttribute("KnockedDown", false)
                local hrp = getHumanoidRootPart(player)
                if hrp and not climbers[player] and not braced[player] then
                    hrp.Anchored = false
                end
                gesture(player, "GetUp") -- from sitting, where Stagger leaves it (WakeUp starts from standing)
            end
        end
    end

    local function count()
        local moved, fell = 0, 0
        for _, w in ipairs(active.woken) do
            local part = w.part
            if not part.Parent then
                fell = fell + 1 -- gone: into the sea
            else
                local d = part.Position - w.from
                if -d.Y > BLOCK_SIZE / 2 or Vector3.new(d.X, 0, d.Z).Magnitude > BLOCK_SIZE then
                    fell = fell + 1
                elseif d.Magnitude > 0.3 then
                    moved = moved + 1
                end
            end
        end
        return moved, fell
    end

    local function watchFaints()
        for player in pairs(bodies()) do
            local n = player:GetAttribute("Faints") or 0
            local seen = faints[player]
            if not seen or n > seen.count then
                faints[player] = { count = n, at = seen and os.clock() or -math.huge }
            end
        end
    end

    local function start(godling)
        if active then
            return nil, "AlreadyShaking"
        end
        local wait = COOLDOWN - (os.clock() - lastEnded)
        if wait > 0 then
            return nil, "TooSoon:" .. math.ceil(wait)
        end
        local s, f = surviving[godling], faints[godling]
        if (s and s.health < MERCY_HEALTH) or (f and os.clock() - f.at < MERCY_AFTER_FAINT) then
            return nil, "GodlingIsWeak"
        end
        local hrp = getHumanoidRootPart(godling)
        if not hrp then
            return nil, "NobodyHere"
        end
        local built = 0
        for _, n in ipairs(piecesNear(hrp.Position, REACH)) do
            if n.part.Anchored then
                built = built + 1
            end
        end
        if built < MIN_PIECES then
            return nil, "NothingBuiltYet"
        end
        skyCounter = skyCounter + 1
        active = { id = skyCounter, t = 0, level = LEVEL, centre = hrp.Position, heading = skyRandom() * 2 * math.pi,
            phases = { skyRandom() * 6.28, skyRandom() * 6.28, skyRandom() * 6.28 }, woken = {}, held = 0 }
        clockPart:SetAttribute("QuakeId", active.id)
        for player in pairs(bodies()) do
            if not climbers[player] then
                gesture(player, "LookAround") -- startled by the rumble; the body braces a moment later
            end
        end
        print(string.format("SKY Earthquake #%d rumbling at (%.1f, %.1f), %d pieces within reach", active.id,
            hrp.Position.X, hrp.Position.Z, built))
        return active.id
    end

    local function tick(dt)
        watchFaints()
        getUp()
        if not active then
            return
        end
        local before = phaseAt(active.t)
        active.t = active.t + dt
        local t, phase = active.t, phaseAt(active.t)
        local level = strength(t)
        if phase == "shaking" and before == "rumble" then
            local godling = godlingPlayer()
            local hrp = godling and getHumanoidRootPart(godling)
            wake(hrp and hrp.Position or active.centre)
            for player, body in pairs(bodies()) do
                if not braced[player] and not climbers[player] and not knocked[player] then
                    knockDown(player, body)
                end
            end
            print(string.format("SKY Earthquake #%d shaking: woke %d pieces; %d hold a body up", active.id,
                #active.woken, active.held))
        end
        if level > 0 then
            local a = groundAccel(t, level)
            for _, w in ipairs(active.woken) do
                local part = w.part
                if part.Parent and not part.Anchored then
                    part:ApplyImpulseAtPosition(a * (-part:GetMass() * dt), part.Position)
                end
            end
        end
        if before == "fade" and phase == "" then -- the ground is still: what moved may settle again
            for _, w in ipairs(active.woken) do
                if w.part.Parent then
                    w.part:SetAttribute("Quaking", false)
                end
            end
        end
        if phase == "" and t >= RUMBLE + SHAKE + FADE + LET_GO then
            for player in pairs(braced) do
                letGo(player)
            end
        end
        clockPart:SetAttribute("Quake", math.floor(level * 100 + 0.5) / 100)
        if clockPart:GetAttribute("QuakePhase") ~= phase then
            clockPart:SetAttribute("QuakePhase", phase)
        end
        if t >= RUMBLE + SHAKE + FADE + AFTER then
            local moved, fell = count()
            clockPart:SetAttribute("QuakeFell", fell)
            print(string.format("SKY Earthquake #%d over: woke %d, moved %d, fell %d", active.id, #active.woken,
                moved, fell))
            active, lastEnded = nil, os.clock()
        end
    end

    local function brace(player)
        local hrp = getHumanoidRootPart(player)
        if not hrp or not active then
            player:SetAttribute("LastActionResult", "BraceFailed:StillGround")
            return
        end
        if climbers[player] then -- the world carries a climbing body; it braces when it steps off
            player:SetAttribute("LastActionResult", "BraceFailed:Climbing")
            return
        end
        local humanoid = getHumanoid(player)
        if humanoid then
            humanoid:CancelMoveTo()
        end
        braced[player] = true
        hrp.Anchored = true -- holding on: nothing the ground does moves it
        player:SetAttribute("Bracing", true)
        player:SetAttribute("LastActionResult", "Braced")
    end

    return { start = start, tick = tick, brace = brace }
end)()

-- The guest panel's player has no body on the island, but the engine gives it one anyway. Parked once on joining, it
-- fell out of the world (a character's body does not stay anchored), and the world put it back on the spawn spot,
-- standing on Godling's head (found 2026-11-02 by the renderer session). So it stands on a pedestal of its own, out
-- of sight under the island, and is put back there if it ever drifts.
sky.pedestal = (function()
    local p = findWorkspaceChild("SkyPedestal") or Instance.new("Part")
    p.Name = "SkyPedestal"
    p.Size = Vector3.new(6, 1, 6)
    p.Position = SKY_PARKING - Vector3.new(0, BODY_ABOVE_FEET + 0.5, 0)
    p.Anchored = true
    p.Transparency = 1
    p.Parent = Workspace
    return p
end)()

function sky.parkGuest()
    for _, player in ipairs(Players:GetPlayers()) do
        local hrp = player.Name == SKY_PLAYER and getHumanoidRootPart(player)
        if hrp and (hrp.Position - SKY_PARKING).Magnitude > 2 then
            hrp.CFrame = CFrame.new(SKY_PARKING)
            hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        end
    end
end

-- What the guest panel can do. Viewers choose what; the world chooses where: near Godling, in view, clear of what
-- it built. Each returns the event's number, or nil and why not.
local SKY_POWERS = {
    Meteor = function(godling)
        local x, z = skySpotNear(godling)
        if not x then
            return nil, "NoClearSpot"
        end
        return announceSkyFall(x, z)
    end,
    Stone = function(godling)
        local x, z = skySpotNear(godling)
        if not x then
            return nil, "NoClearSpot"
        end
        return dropGift("Stone", x, z)
    end,
    Log = function(godling)
        local x, z = skySpotNear(godling)
        if not x then
            return nil, "NoClearSpot"
        end
        return dropGift("Log", x, z)
    end,
    Lightning = function(godling)
        local hrp = getHumanoidRootPart(godling)
        local t = hrp and nearestTree("Tree", hrp.Position)
        if not t then
            return nil, "NoStandingTree"
        end
        return lightningOn(t, hrp.Position)
    end,
    Regrow = function(godling)
        local hrp = getHumanoidRootPart(godling)
        local t = hrp and nearestTree("Stump", hrp.Position)
        if not t then
            return nil, "NoStump"
        end
        skyCounter = skyCounter + 1
        regrowStump(t)
        skyMark("Regrow", skyCounter)(t.part)
        print(string.format("SKY Regrow #%d grew %s back", skyCounter, t.name))
        return skyCounter
    end,
    Earthquake = function(godling)
        return sky.quake.start(godling)
    end,
}

function sky.power(player, inputData)
    if player.Name ~= SKY_PLAYER then -- only the guest panel calls on the sky; Godling cannot
        player:SetAttribute("LastActionResult", "SkyFailed:NotTheSky")
        return
    end
    local name = inputData and tostring(inputData.power or "")
    local power = SKY_POWERS[name]
    local godling = godlingPlayer()
    if not power or not godling then
        player:SetAttribute("LastActionResult", "SkyFailed:" .. (power and "NobodyHere" or "UnknownPower"))
        return
    end
    local id, why = power(godling)
    player:SetAttribute("LastActionResult", id and ("SkyDone:" .. name .. ":" .. id) or ("SkyFailed:" .. why))
end

-- The island never holds a body inside a piece, as Minecraft pushes a player out of a block. The body is exactly two
-- blocks tall, so a beam laid across two-block posts leaves no room under it: in run n7 Godling threw a log across
-- two stacks over its own head, the log settled 0.05 into its head, and the body stood pinned for half an hour. A
-- body found inside a held piece on two looks in a row (0.5 s apart) is moved to the nearest spot where it fits.
-- (A function of its own, as is tickShip's, so its locals stay out of the main chunk's 200; it sets stepBody too.)
local freeTrappedBodies = (function()
    local FREE_SEARCH = 8 -- how far to look for room, in units
    local insideLooks = {}

    local function piecesInBody(player, centre)
        local params = OverlapParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { player.Character, heldBlocksByPlayer[player] }
        -- From a little above the feet to a little over the crown: with anything touching its head the character
        -- controller does not move at all (a body pushed out 1 unit, still under a lintel's edge, stood stuck).
        local probe = Instance.new("Part")
        probe.Size = Vector3.new(1.8, 4.9, 1.8)
        probe.CFrame = CFrame.new(centre + Vector3.new(0, 0.25, 0))
        local hits = Workspace:GetPartsInPart(probe, params)
        probe:Destroy()
        local inside = {}
        for _, hit in ipairs(hits) do
            if hit.Anchored and isSolid(hit) and not isPlacing(hit) then -- loose things the physics pushes aside itself
                table.insert(inside, hit)
            end
        end
        return inside
    end

    local function freeTrappedBodies()
        for _, player in ipairs(Players:GetPlayers()) do
            local hrp = player.Name ~= SKY_PLAYER and getHumanoidRootPart(player)
            if hrp and not player:GetAttribute("Climbing") and #piecesInBody(player, hrp.Position) > 0 then
                insideLooks[player] = (insideLooks[player] or 0) + 1
            else
                insideLooks[player] = nil
            end
            if insideLooks[player] and insideLooks[player] >= 2 then
                insideLooks[player] = nil
                local from = hrp.Position
                local feet = from.Y - BODY_ABOVE_FEET
                local spot = nil
                for r = 1, FREE_SEARCH, 0.5 do
                    for k = 0, 15 do
                        local x, z = from.X + r * math.cos(k * math.pi / 8), from.Z + r * math.sin(k * math.pi / 8)
                        local floor = surfaceTopAt(x, z, feet - 0.6, feet + 0.6) -- the same floor, not the sea
                        if floor and #piecesInBody(player, Vector3.new(x, floor + BODY_ABOVE_FEET, z)) == 0 then
                            spot = Vector3.new(x, floor + BODY_ABOVE_FEET, z)
                            break
                        end
                    end
                    if spot then
                        break
                    end
                end
                if spot then
                    hrp.Position = spot
                    hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    local humanoid = getHumanoid(player)
                    if humanoid then
                        humanoid:CancelMoveTo()
                    end
                    player:SetAttribute("Freed", (player:GetAttribute("Freed") or 0) + 1)
                    print(string.format("FREED %s from inside a piece: (%.1f, %.1f) to (%.1f, %.1f)", player.Name,
                        from.X, from.Z, spot.X, spot.Z))
                end
            end
        end
    end

    -- Stepping up and down (the user's choice, after run n7, where nothing above two blocks was in reach and the ladder
    -- seldom worked out; ADR-010). The body steps onto something at most one block above its feet, or down onto a floor
    -- at most one block below, right beside it, if it fits there. As in Minecraft, its own steps and walls become a way
    -- up; anything higher still needs a ladder. Stepping down is the hop off an edge, done by the world: walking off a
    -- one-block step hemmed in by what was just built on it left the body hanging on the edge.
    local STEP_MAX, STEP_REACH = 2.6, 2.8

    stepBody = function(player, inputData, down)
        local kind = down and "StepDown" or "StepUp"
        local hrp = getHumanoidRootPart(player)
        local to = inputData and inputData.position
        if not hrp or type(to) ~= "table" or not tonumber(to[1]) or not tonumber(to[#to]) then
            player:SetAttribute("LastActionResult", kind .. "Failed:BadTarget")
            return
        end
        if climbers[player] then
            player:SetAttribute("LastActionResult", kind .. "Failed:Busy")
            return
        end
        local x, z = tonumber(to[1]), tonumber(to[#to]) -- [x, z] or [x, y, z]
        local body = hrp.Position
        local feet = body.Y - BODY_ABOVE_FEET
        if Vector3.new(x - body.X, 0, z - body.Z).Magnitude > STEP_REACH then
            player:SetAttribute("LastActionResult", kind .. "Failed:TooFar")
            return
        end
        local top = down and surfaceTopAt(x, z, feet - STEP_MAX - 0.2, feet - 0.6)
            or surfaceTopAt(x, z, feet + 0.6, feet + STEP_MAX)
        if not top then
            player:SetAttribute("LastActionResult", kind .. "Failed:" .. ((not down and surfaceTopAt(x, z, feet + STEP_MAX,
                feet + 60)) and "TooHigh" or "NothingToStepOn"))
            return
        end
        local landing = Vector3.new(x, top + BODY_ABOVE_FEET, z)
        if #piecesInBody(player, landing) > 0 then
            player:SetAttribute("LastActionResult", kind .. "Failed:NoRoom")
            return
        end
        local humanoid = getHumanoid(player)
        if humanoid then
            humanoid:CancelMoveTo()
        end
        hrp.Anchored = true -- the world moves the body, as on a ladder: over the edge and up or down
        local over = Vector3.new((body.X + x) / 2, math.max(body.Y, landing.Y) + 0.4, (body.Z + z) / 2)
        climbers[player] = { path = { body, over, landing }, times = { 0.3, 0.3 }, leg = 1, t = 0 }
        player:SetAttribute("Climbing", true)
        player:SetAttribute("LastActionResult", kind .. "Started:0.6")
    end

    return freeTrappedBodies
end)()

--------------------------------------------------------------------------------
-- MAIN LOOP
--------------------------------------------------------------------------------

RunService.Heartbeat:Connect(function(dt)
    for _, player in ipairs(Players:GetPlayers()) do
        local hrp = getHumanoidRootPart(player)
        if hrp and hrp.Position.Y < OUT_OF_BOUNDS_Y then
            resetPlayerToSpawn(player)
        end
    end
    tickSurvival(dt) -- hunger and health
    moveFish(dt)
    tickClock(dt)
    tickFires()
    tickWeather(dt) -- rain, cold and shelter

    -- Update held blocks (a block just picked up rises into the hands over LIFT_SECONDS)
    for player, heldBlock in pairs(heldBlocksByPlayer) do
        local hrp = getHumanoidRootPart(player)
        if hrp and heldBlock then
            local target = hrp.Position + HOLD_OFFSET
            local lift = liftingBlocks[player]
            if lift and lift.block == heldBlock and lift.elapsed < LIFT_SECONDS then
                lift.elapsed = lift.elapsed + dt
                local alpha = math.min(lift.elapsed / LIFT_SECONDS, 1)
                local t = 1 - (1 - alpha) * (1 - alpha)
                heldBlock.Position = lift.from + (target - lift.from) * t
            else
                liftingBlocks[player] = nil
                if heldBlock:GetAttribute("RenderRole") == "Ladder" then
                    -- Carried lying flat along the way the body faces; set down, it stands up again.
                    heldBlock.CFrame = CFrame.new(target) * (hrp.CFrame - hrp.CFrame.Position)
                        * CFrame.fromOrientation(math.rad(90), 0, 0)
                else
                    heldBlock.Position = target
                end
            end
            heldBlock.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            heldBlock.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end
    end

    supplyTimer = supplyTimer + dt
    if supplyTimer >= SUPPLY_INTERVAL then
        supplyTimer = 0
        if SUPPLY_FROM_SKY and looseGroundCubes() < SUPPLY_WHEN_FEWER_THAN then
            deliverCube()
        end
    end

    advanceClimbers(dt)
    settleTimer = settleTimer + dt
    if settleTimer >= 0.5 then
        settleTimer = 0
        settleResting() -- pieces that came to rest square into their cells and hold there
        freeTrappedBodies() -- and a body never stays shut inside one
        sky.parkGuest() -- the guest panel's body stays out of sight
    end
    advanceTurners(dt)
    if SKY_TEST_EVERY > 0 then
        skyTimer = skyTimer + dt
        if skyTimer >= SKY_TEST_EVERY then
            skyTimer = 0
            local player = godlingPlayer()
            if player then
                local x, z = skySpotNear(player)
                if x then
                    announceSkyFall(x, z)
                end
            end
        end
    end
    advanceSkyFalls()
    sky.quake.tick(dt) -- an earthquake shakes what is loose
    tickDriftwood(dt) -- now and then the sea leaves a log on the beach
    tickShip(dt) -- and a ship passes far out
    keepsakeTimer = keepsakeTimer + dt
    if keepsakeTimer >= 10 then
        keepsakeTimer = 0
        restoreKeepsakes() -- tools, the ladder and boulders lost in the sea turn up again at home
        regrowTrees()
    end

    -- Animate placing blocks
    local i = 1
    while i <= #placingBlocks do
        local p = placingBlocks[i]
        p.elapsed = p.elapsed + dt
        local alpha = math.min(p.elapsed / p.duration, 1)
        -- Smooth ease-out
        local t = 1 - (1 - alpha) * (1 - alpha)
        p.block.CFrame = p.startCFrame:Lerp(p.targetCFrame, t)

        if alpha >= 1 then
            p.block.Anchored = p.block:GetAttribute("RenderRole") == "Ladder" -- a set-up ladder stands by itself
            p.block.CanCollide = true
            setPickupMetadata(
                p.block,
                p.block:GetAttribute("ItemColorName"),
                p.block:GetAttribute("RenderRole")
            )
            local impactState = rockImpactStates[p.block]
            if impactState then
                impactState.ignoreUntil = os.clock() + 0.15
            end
            table.remove(placingBlocks, i)
        else
            i = i + 1
        end
    end

    local thrownIndex = 1
    while thrownIndex <= #thrownBlocks do
        local thrown = thrownBlocks[thrownIndex]
        if not thrown.block.Parent then
            table.remove(thrownBlocks, thrownIndex)
        else
            thrown.elapsed = thrown.elapsed + dt
            if thrown.elapsed >= thrown.duration then
                thrown.block.CanCollide = true
                table.remove(thrownBlocks, thrownIndex)
            else
                thrownIndex = thrownIndex + 1
            end
        end
    end

    for block, _ in pairs(trackedBlocks) do
        if not block.Parent then
            trackedBlocks[block] = nil
            rockImpactStates[block] = nil
        elseif block.Position.Y < OUT_OF_BOUNDS_Y then
            destroyBlock(block)
        end
    end
end)

